typedef struct {
	uint8_t *data;
	size_t len, cap;
} Buf;

static void binit(Buf *b) {
	b->data=NULL;
	b->len=b->cap=0;
}

static void bput(Buf *b, const void *p, size_t n) {
	if(b->len+n>b->cap) {
		size_t nc=b->cap?b->cap*2:256;
		while(nc<b->len+n) nc*=2;
		b->data=(uint8_t*)realloc(b->data,nc);
		b->cap=nc;
	}
	memcpy(b->data+b->len,p,n);
	b->len+=n;
}

static void b8(Buf *b, uint8_t x) {
	bput(b,&x,1);
}

static char *buf_to_cstr(Buf *b) {
	b8(b, 0);
	char *s = (char*)malloc(b->len);
	if(!s) {
		perror("malloc");
		exit(1);
	}
	memcpy(s, b->data, b->len);
	s[b->len-1] = '\0';
	free(b->data);
	b->data=NULL;
	b->len=b->cap=0;
	return s;
}

static void le16(uint8_t *p, uint16_t x) {
	p[0]=x;
	p[1]=x>>8;
}

static void le32(uint8_t *p, uint32_t x) {
	p[0]=x;
	p[1]=x>>8;
	p[2]=x>>16;
	p[3]=x>>24;
}

static void le64(uint8_t *p, uint64_t x) {
	for(int i=0; i<8; i++) p[i]=(uint8_t)(x>>(8*i));
}

typedef struct {
	Buf code;
} Code;

static size_t cpos(Code *c) {
	return c->code.len;
}

static void c8(Code *c, uint8_t x) {
	b8(&c->code,x);
}

static void c32(Code *c, uint32_t x) {
	bput(&c->code,&x,4);
}

static void c64(Code *c, uint64_t x) {
	bput(&c->code,&x,8);
}

static void patch32(Buf *b, size_t off, uint32_t v) {
	b->data[off+0]=v;
	b->data[off+1]=v>>8;
	b->data[off+2]=v>>16;
	b->data[off+3]=v>>24;
}

typedef struct {
	Buf pool;
	size_t *offs;
	size_t n, cap;
} StrPool;

static void sp_init(StrPool *sp) {
	binit(&sp->pool);
	sp->offs=NULL;
	sp->n=sp->cap=0;
}

static size_t sp_add(StrPool *sp, const char *s) {
	for(size_t i=0; i<sp->n; i++) {
		const char *ex = (const char*)(sp->pool.data + sp->offs[i]);
		if(strcmp(ex, s)==0) return i;
	}
	size_t off = sp->pool.len;
	size_t n = strlen(s);
	bput(&sp->pool, s, n+1);
	if(sp->n==sp->cap) {
		sp->cap=sp->cap?sp->cap*2:64;
		sp->offs=(size_t*)realloc(sp->offs, sp->cap*sizeof(size_t));
	}
	sp->offs[sp->n++] = off;
	return sp->n-1;
}

