typedef struct {
	char **v;
	int n, cap;
} StrV;

static void sv_push(StrV *sv, char *s) {
	if(sv->n==sv->cap) {
		sv->cap=sv->cap?sv->cap*2:16;
		sv->v=(char**)realloc(sv->v,sv->cap*sizeof(char*));
	}
	sv->v[sv->n++]=s;
}

typedef struct {
	StrV argv;
	char *in_redir;
	char *out_redir;
	int out_append;
	char *err_redir;
	int err_append;
	char *hstr;
	StrV penv;
	StrV pold;
} Stage;

typedef struct {
	Stage *v;
	int n, cap;
	int neg, bg;
} Pipeline;

typedef struct {
	Pipeline pl;
	int cond;
} ScriptEntry;

static void pl_push(Pipeline *p, Stage st) {
	if(p->n==p->cap) {
		p->cap=p->cap?2*p->cap:4;
		p->v=(Stage*)realloc(p->v,p->cap*sizeof(Stage));
	}
	p->v[p->n++]=st;
}

typedef struct {
	ScriptEntry *v;
	int n, cap;
} Script;

enum {
	COND_ALWAYS = 0,
	COND_PREV_SUCCESS = 1,
	COND_PREV_FAILURE = 2,
};

static void sc_push(Script *s, Pipeline p, int cond) {
	if(s->n==s->cap) {
		s->cap=s->cap?2*s->cap:4;
		s->v=(ScriptEntry*)realloc(s->v,s->cap*sizeof(ScriptEntry));
	}
	s->v[s->n++]=(ScriptEntry){.pl=p,.cond=cond};
}

static char *readfile(const char *path) {
	FILE *f=fopen(path,"rb");
	if(!f) {
		perror("open");
		exit(1);
	}
	fseek(f,0,SEEK_END);
	long n=ftell(f);
	fseek(f,0,SEEK_SET);
	char *buf=(char*)malloc(n+1);
	if(!buf) {
		perror("malloc");
		exit(1);
	}
	fread(buf,1,n,f);
	buf[n]=0;
	fclose(f);
	return buf;
}

static void parse_error(const char *msg) {
	fprintf(stderr, "parse error: %s\n", msg);
	exit(1);
}

static void skip_inline_ws(const char **pp) {
	while(**pp==' ' || **pp=='\t' || **pp=='\r') (*pp)++;
}

static int is_token_terminator(char c) {
	return c=='\0' || c==' ' || c=='\t' || c=='\r' || c=='\n' || c=='|' || c==';' || c=='<' || c=='>' || c=='&' || c=='(' || c==')' || c=='{' || c=='}';
}

static char *parse_ident(const char **pp) {
	const char *p = *pp;
	while(*p==' ' || *p=='\t' || *p=='\r' || *p=='\n' || *p==';') p++;
	if(!*p) { *pp = p; return NULL; }
	const char *start = p;
	while(*p && *p!=' ' && *p!='\t' && *p!='\r' && *p!='\n' && *p!=';') p++;
	size_t len = (size_t)(p - start);
	char *w = (char*)malloc(len + 1);
	memcpy(w, start, len);
	w[len] = '\0';
	*pp = p;
	return w;
}

static const char *ap;
static int aerr, anoev;
static char **g_fa;
static int g_fn, g_fdep;

static long acomma(void);
static long aasg(void);

static void aws(void) {
	while(*ap==' ' || *ap=='\t' || *ap=='\n' || *ap=='\r') ap++;
}

static int isnm(char ch) {
	return (ch>='A' && ch<='Z') || (ch>='a' && ch<='z') || (ch>='0' && ch<='9') || ch=='_';
}

static char *fav(const char *n) {
	if(g_fdep>0 && n[0]>='0' && n[0]<='9' && !n[1]) {
		int k = n[0]-'0';
		if(k==0) return getenv("0");
		return k<=g_fn ? g_fa[k-1] : NULL;
	}
	return getenv(n);
}

static long arith(const char *s);

static long avar(const char *n) {
	static int dep = 0;
	char *v = fav(n);
	if(!v || !*v) return 0;
	char *e;
	long x = strtol(v, &e, 0);
	if(*e=='\0') return x;
	if(dep>32) return 0;
	dep++;
	const char *sp = ap;
	int se = aerr;
	x = arith(v);
	ap = sp;
	aerr = se;
	dep--;
	return x;
}

static void aset(const char *n, long v) {
	if(anoev) return;
	char b[32];
	snprintf(b, sizeof(b), "%ld", v);
	setenv(n, b, 1);
}

static int anm(char *n) {
	int i = 0;
	while(isnm(*ap) && i<127) n[i++] = *ap++;
	n[i] = '\0';
	return i;
}

static long anum(void) {
	char *e;
	long v;
	const char *q = ap;
	while(isnm(*q)) q++;
	if(*q=='#') {
		int base = (int)strtol(ap, NULL, 10);
		ap = q+1;
		v = 0;
		while(isnm(*ap) || *ap=='@') {
			int d;
			char ch = *ap;
			if(ch>='0' && ch<='9') d = ch-'0';
			else if(ch>='a' && ch<='z') d = ch-'a'+10;
			else if(ch>='A' && ch<='Z') d = base<=36 ? ch-'A'+10 : ch-'A'+36;
			else if(ch=='@') d = 62;
			else d = 63;
			if(d>=base) aerr = 1;
			v = v*base+d;
			ap++;
		}
		return v;
	}
	v = strtol(ap, &e, 0);
	ap = e;
	if(isnm(*ap)) aerr = 1;
	return v;
}

static long aprim(void) {
	char n[128];
	aws();
	if(*ap=='(') {
		ap++;
		long v = acomma();
		aws();
		if(*ap==')') ap++;
		else aerr = 1;
		return v;
	}
	if(*ap=='$') {
		ap++;
		if(*ap=='{') {
			ap++;
			anm(n);
			if(*ap=='}') ap++;
		} else anm(n);
		return avar(n);
	}
	if(*ap>='0' && *ap<='9') return anum();
	if(isnm(*ap)) {
		anm(n);
		long v = avar(n);
		aws();
		if(ap[0]=='+' && ap[1]=='+') { ap += 2; aset(n, v+1); }
		else if(ap[0]=='-' && ap[1]=='-') { ap += 2; aset(n, v-1); }
		return v;
	}
	aerr = 1;
	return 0;
}

static long aun(void) {
	aws();
	if((ap[0]=='+' && ap[1]=='+') || (ap[0]=='-' && ap[1]=='-')) {
		int d = ap[0]=='+' ? 1 : -1;
		ap += 2;
		aws();
		char n[128];
		if(!anm(n)) { aerr = 1; return 0; }
		long v = avar(n)+d;
		aset(n, v);
		return v;
	}
	if(*ap=='!') { ap++; return !aun(); }
	if(*ap=='~') { ap++; return ~aun(); }
	if(*ap=='-') { ap++; return -aun(); }
	if(*ap=='+') { ap++; return aun(); }
	return aprim();
}

static long apow(void) {
	long b = aun();
	aws();
	if(ap[0]=='*' && ap[1]=='*') {
		ap += 2;
		long e = apow();
		long r = 1;
		if(e<0) { aerr = 3; return 0; }
		while(e-->0) r *= b;
		return r;
	}
	return b;
}

static long amul(void) {
	long v = apow();
	for(;;) {
		aws();
		char o = *ap;
		if((o=='*' || o=='/' || o=='%') && ap[1]!='=' && ap[1]!='*') {
			ap++;
			long r = apow();
			if(o=='*') v *= r;
			else if(r==0) { if(!anoev) aerr = 2; v = 0; }
			else if(o=='/') v /= r;
			else v %= r;
		} else return v;
	}
}

static long aadd(void) {
	long v = amul();
	for(;;) {
		aws();
		char o = *ap;
		if((o=='+' || o=='-') && ap[1]!='=' && ap[1]!=o) {
			ap++;
			long r = amul();
			v = o=='+' ? v+r : v-r;
		} else return v;
	}
}

static long ashf(void) {
	long v = aadd();
	for(;;) {
		aws();
		if((ap[0]=='<' || ap[0]=='>') && ap[1]==ap[0] && ap[2]!='=') {
			char o = *ap;
			ap += 2;
			long r = aadd();
			v = o=='<' ? (long)((unsigned long)v<<r) : v>>r;
		} else return v;
	}
}

static long arel(void) {
	long v = ashf();
	for(;;) {
		aws();
		if((ap[0]=='<' || ap[0]=='>') && ap[1]!=ap[0]) {
			char o = *ap++;
			int e = 0;
			if(*ap=='=') { e = 1; ap++; }
			long r = ashf();
			if(o=='<') v = e ? v<=r : v<r;
			else v = e ? v>=r : v>r;
		} else return v;
	}
}

static long aeq(void) {
	long v = arel();
	for(;;) {
		aws();
		if((ap[0]=='=' || ap[0]=='!') && ap[1]=='=') {
			char o = *ap;
			ap += 2;
			long r = arel();
			v = o=='=' ? v==r : v!=r;
		} else return v;
	}
}

static long aband(void) {
	long v = aeq();
	for(;;) {
		aws();
		if(ap[0]=='&' && ap[1]!='&' && ap[1]!='=') { ap++; v &= aeq(); }
		else return v;
	}
}

static long abxor(void) {
	long v = aband();
	for(;;) {
		aws();
		if(ap[0]=='^' && ap[1]!='=') { ap++; v ^= aband(); }
		else return v;
	}
}

static long abor(void) {
	long v = abxor();
	for(;;) {
		aws();
		if(ap[0]=='|' && ap[1]!='|' && ap[1]!='=') { ap++; v |= abxor(); }
		else return v;
	}
}

static long aland(void) {
	long v = abor();
	for(;;) {
		aws();
		if(ap[0]=='&' && ap[1]=='&') {
			ap += 2;
			int s = anoev;
			if(!v) anoev = 1;
			long r = abor();
			anoev = s;
			v = v && r;
		} else return v;
	}
}

static long alor(void) {
	long v = aland();
	for(;;) {
		aws();
		if(ap[0]=='|' && ap[1]=='|') {
			ap += 2;
			int s = anoev;
			if(v) anoev = 1;
			long r = aland();
			anoev = s;
			v = v || r;
		} else return v;
	}
}

static long acond(void) {
	long c = alor();
	aws();
	if(*ap=='?') {
		ap++;
		int s = anoev;
		if(!c) anoev = 1;
		long a = aasg();
		anoev = s;
		aws();
		if(*ap==':') ap++;
		else aerr = 1;
		if(c) anoev = 1;
		long b = aasg();
		anoev = s;
		return c ? a : b;
	}
	return c;
}

static long aasg(void) {
	aws();
	const char *sv = ap;
	char n[128];
	if(isnm(*ap) && !(*ap>='0' && *ap<='9')) {
		anm(n);
		aws();
		char o = 0;
		int l = 0;
		if(ap[0]=='=' && ap[1]!='=') { o = '='; l = 1; }
		else if(strchr("+-*/%&^|", ap[0]) && ap[0] && ap[1]=='=') { o = ap[0]; l = 2; }
		else if((ap[0]=='<' || ap[0]=='>') && ap[1]==ap[0] && ap[2]=='=') { o = ap[0]; l = 3; }
		if(o) {
			ap += l;
			long r = aasg();
			long v = o=='=' ? 0 : avar(n);
			switch(o) {
			case '=': v = r; break;
			case '+': v += r; break;
			case '-': v -= r; break;
			case '*': v *= r; break;
			case '/': if(r) v /= r; else aerr = 2; break;
			case '%': if(r) v %= r; else aerr = 2; break;
			case '&': v &= r; break;
			case '^': v ^= r; break;
			case '|': v |= r; break;
			case '<': v = (long)((unsigned long)v<<r); break;
			case '>': v >>= r; break;
			}
			aset(n, v);
			return v;
		}
		ap = sv;
	}
	return acond();
}

static long acomma(void) {
	long v = aasg();
	aws();
	while(*ap==',') {
		ap++;
		v = aasg();
		aws();
	}
	return v;
}

static long arith(const char *s) {
	ap = s;
	aerr = 0;
	aws();
	if(!*ap) return 0;
	long v = acomma();
	aws();
	if(*ap) aerr = 1;
	if(aerr==2) fprintf(stderr, "sh2elf: %s: division by 0\n", s);
	else if(aerr==3) fprintf(stderr, "sh2elf: %s: exponent less than 0\n", s);
	else if(aerr) fprintf(stderr, "sh2elf: %s: arithmetic syntax error\n", s);
	return aerr ? 0 : v;
}

static const char *mpar(const char *p) {
	int d = 0;
	while(*p) {
		if(*p=='(') d++;
		else if(*p==')') {
			if(d==0 && p[1]==')') return p;
			if(d>0) d--;
		}
		p++;
	}
	return NULL;
}

static void csub(const char *s, Buf *b) {
	FILE *fp = popen(s, "r");
	if(!fp) return;
	Buf t;
	binit(&t);
	char cb[4096];
	size_t nr;
	while((nr = fread(cb, 1, sizeof(cb), fp))>0) bput(&t, cb, nr);
	pclose(fp);
	while(t.len>0 && (t.data[t.len-1]=='\n' || t.data[t.len-1]=='\r')) t.len--;
	if(t.len) bput(b, t.data, t.len);
	free(t.data);
}

static void bout(Buf *b, long v) {
	b8(b, (uint8_t)v);
	if(v==1) b8(b, 1);
}

static void rtsn(Buf *b, char k) {
	b8(b, 1);
	b8(b, (uint8_t)k);
}

static void cmod(char *s, char o, int all) {
	for(int i = 0; s[i]; i++) {
		if(o=='^' && s[i]>='a' && s[i]<='z') s[i] -= 32;
		else if(o==',' && s[i]>='A' && s[i]<='Z') s[i] += 32;
		else if(o=='~' && s[i]>='a' && s[i]<='z') s[i] -= 32;
		else if(o=='~' && s[i]>='A' && s[i]<='Z') s[i] += 32;
		if(!all) break;
	}
}

static char *xword(const char *s);

static void xbr(const char **pp, Buf *buf) {
	const char *p = *pp;
	char vname[128];
	int vi = 0;
	int ind = 0;
	if(*p=='#' && p[1]!='}' && p[1]!='\0') {
		p++;
		while(*p && *p!='}' && vi < 127) vname[vi++] = *p++;
		vname[vi] = '\0';
		if(*p=='}') p++;
		*pp = p;
		char *val = fav(vname);
		if(g_fdep==0 && ((vname[0]>='0' && vname[0]<='9') || vname[0]=='@' || vname[0]=='*')) val = NULL;
		size_t vlen = val ? strlen(val) : 0;
		char lbuf[32];
		snprintf(lbuf, sizeof(lbuf), "%zu", vlen);
		bput(buf, lbuf, strlen(lbuf));
		return;
	}
	if(*p=='#' && p[1]=='}') {
		p += 2;
		*pp = p;
		if(g_fdep>0) {
			char lb[16];
			snprintf(lb, sizeof(lb), "%d", g_fn);
			bput(buf, lb, strlen(lb));
		} else rtsn(buf, '#');
		return;
	}
	if(*p=='!') { ind = 1; p++; }
	if((*p=='?' || *p=='$' || *p=='!' || *p=='@' || *p=='*') && p[1]=='}' && !ind) {
		char k = *p=='$' ? '$' : *p;
		p += 2;
		*pp = p;
		if(g_fdep>0 && (k=='@' || k=='*')) {
			for(int i = 0; i<g_fn; i++) {
				if(i) b8(buf, ' ');
				bput(buf, g_fa[i], strlen(g_fa[i]));
			}
		} else rtsn(buf, k);
		return;
	}
	while(*p && *p!='}' && *p!=':' && *p!='-' && *p!='=' && *p!='+' && *p!='?' && *p!='#' && *p!='%' && *p!='/' && *p!='^' && *p!=',' && *p!='~' && vi < 127) vname[vi++] = *p++;
	vname[vi] = '\0';
	if(ind) {
		char *iv = fav(vname);
		snprintf(vname, sizeof(vname), "%s", iv ? iv : "");
	}
	if(g_fdep==0 && vname[0]>='0' && vname[0]<='9' && !vname[1] && *p=='}') {
		p++;
		*pp = p;
		rtsn(buf, vname[0]);
		return;
	}
	if(!ind && (strcmp(vname,"PPID")==0 || strcmp(vname,"RANDOM")==0) && *p=='}') {
		p++;
		*pp = p;
		rtsn(buf, vname[0]);
		return;
	}
	char op = '\0';
	int is_double = 0, colon = 0;
	if(*p==':' && p[1] && strchr("-=+?", p[1])) { p++; colon = 1; op = *p++; }
	else if(*p==':') { p++; op = ':'; }
	else if(*p=='-' || *p=='=' || *p=='+' || *p=='?') op = *p++;
	else if(*p=='#') { p++; op = '#'; if(*p=='#') { p++; is_double = 1; } }
	else if(*p=='%') { p++; op = '%'; if(*p=='%') { p++; is_double = 1; } }
	else if(*p=='/') { p++; op = '/'; if(*p=='/') { p++; is_double = 1; } }
	else if(*p=='^' || *p==',' || *p=='~') { op = *p++; if(*p==op) { p++; is_double = 1; } }
	char pat[512], rep[512];
	int pi = 0, ri = 0, dep = 0;
	pat[0] = rep[0] = '\0';
	if(op=='/') {
		while(*p && *p!='}' && *p!='/' && pi < 511) pat[pi++] = *p++;
		pat[pi] = '\0';
		if(*p=='/') p++;
		while(*p && *p!='}' && ri < 511) rep[ri++] = *p++;
		rep[ri] = '\0';
	} else if(op) {
		while(*p && (*p!='}' || dep>0) && pi < 511) {
			if(*p=='{') dep++;
			else if(*p=='}') dep--;
			pat[pi++] = *p++;
		}
		pat[pi] = '\0';
	}
	if(*p=='}') p++;
	*pp = p;
	char *val = fav(vname);
	int set = val!=NULL && (!colon || *val);
	if(op=='-' || op=='=' || op=='+' || op=='?') {
		char *w = xword(pat);
		if(op=='-') {
			if(set) bput(buf, val, strlen(val));
			else bput(buf, w, strlen(w));
		} else if(op=='=') {
			if(!set) { setenv(vname, w, 1); val = getenv(vname); }
			bput(buf, val, strlen(val));
		} else if(op=='+') {
			if(set) bput(buf, w, strlen(w));
		} else {
			if(set) bput(buf, val, strlen(val));
			else {
				fprintf(stderr, "sh2elf: %s: %s\n", vname, *w ? w : "parameter null or not set");
				exit(1);
			}
		}
		free(w);
		return;
	}
	if(op==':') {
		char *c2 = strchr(pat, ':');
		if(c2) *c2 = '\0';
		long vl = val ? (long)strlen(val) : 0;
		long off = arith(pat);
		if(off<0) off += vl;
		if(off<0 || off>vl) return;
		long ln = vl-off;
		if(c2) {
			ln = arith(c2+1);
			if(ln<0) ln = vl-off+ln;
			if(ln<0) {
				fprintf(stderr, "sh2elf: %s: substring expression < 0\n", c2+1);
				return;
			}
			if(off+ln>vl) ln = vl-off;
		}
		if(ln>0) bput(buf, val+off, (size_t)ln);
		return;
	}
	if(op=='^' || op==',' || op=='~') {
		if(val) {
			char *t = strdup(val);
			cmod(t, op, is_double);
			bput(buf, t, strlen(t));
			free(t);
		}
		return;
	}
	if(op=='#') {
		if(val) {
			size_t vlen = strlen(val);
			size_t match_len = 0;
			for(size_t k = (is_double ? vlen : 1); is_double ? (k > 0) : (k <= vlen); is_double ? k-- : k++) {
				char saved = val[k];
				val[k] = '\0';
				if(fnmatch(pat, val, 0) == 0) { match_len = k; val[k] = saved; if(!is_double) break; }
				val[k] = saved;
			}
			bput(buf, val + match_len, vlen - match_len);
		}
	} else if(op=='%') {
		if(val) {
			size_t vlen = strlen(val);
			size_t match_at = vlen;
			for(size_t k = (is_double ? 0 : vlen - 1); is_double ? (k < vlen) : (k <= vlen); is_double ? k++ : k--) {
				if(fnmatch(pat, val + k, 0) == 0) { match_at = k; if(!is_double) break; }
				if(k == 0) break;
			}
			bput(buf, val, match_at);
		}
	} else if(op=='/') {
		if(val) {
			size_t vlen = strlen(val), plen = strlen(pat);
			if(plen == 0) {
				bput(buf, val, vlen);
			} else {
				size_t i = 0;
				while(i < vlen) {
					if(strncmp(val + i, pat, plen) == 0) {
						bput(buf, rep, strlen(rep));
						i += plen;
						if(!is_double) { bput(buf, val + i, vlen - i); break; }
					} else {
						b8(buf, (uint8_t)val[i++]);
					}
				}
			}
		}
	} else {
		if(val) bput(buf, val, strlen(val));
	}
}

static void ansic(const char **pp, Buf *b) {
	const char *p = *pp;
	while(*p && *p!='\'') {
		if(*p!='\\' || !p[1]) { b8(b, (uint8_t)*p++); continue; }
		p++;
		char e = *p++;
		int v = -1;
		switch(e) {
		case 'n': v = '\n'; break;
		case 't': v = '\t'; break;
		case 'r': v = '\r'; break;
		case 'a': v = 7; break;
		case 'b': v = 8; break;
		case 'e': case 'E': v = 27; break;
		case 'f': v = 12; break;
		case 'v': v = 11; break;
		case '\\': v = '\\'; break;
		case '\'': v = '\''; break;
		case '"': v = '"'; break;
		case '?': v = '?'; break;
		case 'x': {
			int n = 0, k = 0;
			while(k<2 && ((*p>='0' && *p<='9') || (*p>='a' && *p<='f') || (*p>='A' && *p<='F'))) {
				n = n*16 + (*p<='9' ? *p-'0' : (*p|32)-'a'+10);
				p++;
				k++;
			}
			v = k ? n : -2;
			break;
		}
		case 'c':
			if(*p) { v = *p++ & 31; }
			break;
		default:
			if(e>='0' && e<='7') {
				int n = e-'0', k = 1;
				while(k<3 && *p>='0' && *p<='7') { n = n*8 + (*p++-'0'); k++; }
				v = n & 255;
			} else {
				b8(b, '\\');
				v = e;
			}
		}
		if(v==-2) { b8(b, '\\'); b8(b, 'x'); }
		else if(v>0) bout(b, v);
	}
	if(*p!='\'') parse_error("unterminated $' quote");
	p++;
	*pp = p;
}

static void xdol(const char **pp, Buf *buf, int dq) {
	const char *p = *pp;
	if(*p=='(' && p[1]=='(') {
		const char *e = mpar(p+2);
		if(e) {
			size_t n = (size_t)(e-(p+2));
			char *ex = (char*)malloc(n+1);
			memcpy(ex, p+2, n);
			ex[n] = '\0';
			char r[32];
			snprintf(r, sizeof(r), "%ld", arith(ex));
			bput(buf, r, strlen(r));
			free(ex);
			*pp = e+2;
			return;
		}
	}
	if(*p=='(') {
		p++;
		Buf sc;
		binit(&sc);
		int depth = 1;
		while(*p) {
			if(*p=='(') depth++;
			else if(*p==')') {
				depth--;
				if(depth==0) { p++; break; }
			}
			b8(&sc, (uint8_t)*p++);
		}
		char *s = buf_to_cstr(&sc);
		csub(s, buf);
		free(s);
		*pp = p;
		return;
	}
	if(*p=='\'' && !dq) {
		p++;
		ansic(&p, buf);
		*pp = p;
		return;
	}
	if(*p=='{') {
		p++;
		xbr(&p, buf);
		*pp = p;
		return;
	}
	if(*p=='?' || *p=='$' || *p=='!') {
		rtsn(buf, *p);
		*pp = p+1;
		return;
	}
	if(*p=='#' || *p=='@' || *p=='*' || (*p>='0' && *p<='9')) {
		char k = *p++;
		*pp = p;
		if(g_fdep>0 && k!='0') {
			if(k=='#') {
				char lb[16];
				snprintf(lb, sizeof(lb), "%d", g_fn);
				bput(buf, lb, strlen(lb));
			} else if(k=='@' || k=='*') {
				for(int i = 0; i<g_fn; i++) {
					if(i) b8(buf, ' ');
					bput(buf, g_fa[i], strlen(g_fa[i]));
				}
			} else if(k-'0'<=g_fn) bput(buf, g_fa[k-'1'], strlen(g_fa[k-'1']));
		} else rtsn(buf, k);
		return;
	}
	if(isnm(*p)) {
		char vname[128];
		int vi = 0;
		while(isnm(*p) && vi < 127) vname[vi++] = *p++;
		vname[vi] = '\0';
		*pp = p;
		if(strcmp(vname,"PPID")==0 || strcmp(vname,"RANDOM")==0) {
			rtsn(buf, vname[0]);
			return;
		}
		char *val = getenv(vname);
		if(val) bput(buf, val, strlen(val));
		return;
	}
	b8(buf, '$');
}

static const char *bval(const char *p) {
	int d = 0, ok = 0;
	const char *q = p;
	while(*q) {
		char ch = *q;
		if(ch==' ' || ch=='\t' || ch=='\n' || ch=='\r' || ch==';' || ch=='|' || ch=='&' || ch=='<' || ch=='>' || ch=='(' || ch==')') return NULL;
		if(ch=='\\' && q[1]) { q += 2; continue; }
		if(ch=='\'' || ch=='"') {
			char e = ch;
			q++;
			while(*q && *q!=e) { if(e=='"' && *q=='\\' && q[1]) q++; q++; }
			if(!*q) return NULL;
			q++;
			continue;
		}
		if(ch=='$' && q[1]=='{') {
			int e = 0;
			q += 2;
			while(*q && (*q!='}' || e)) { if(*q=='{') e++; else if(*q=='}') e--; q++; }
			if(!*q) return NULL;
			q++;
			continue;
		}
		if(ch=='{') d++;
		else if(ch=='}') {
			d--;
			if(d==0) return ok ? q : NULL;
		} else if(d==1 && (ch==',' || (ch=='.' && q[1]=='.'))) ok = 1;
		q++;
	}
	return NULL;
}

static void unmark(char *s) {
	for(; *s; s++) {
		if(*s==2) *s = '{';
		else if(*s==3) *s = '}';
		else if(*s==4) *s = ',';
	}
}

static int bseq(const char *s, StrV *o) {
	char a[64], b[64];
	long st = 1;
	const char *d = strstr(s, "..");
	if(!d || d==s || d-s>=63) return 0;
	memcpy(a, s, (size_t)(d-s));
	a[d-s] = '\0';
	const char *r = d+2;
	const char *d2 = strstr(r, "..");
	size_t bl = d2 ? (size_t)(d2-r) : strlen(r);
	if(!bl || bl>=63) return 0;
	memcpy(b, r, bl);
	b[bl] = '\0';
	if(d2) {
		char *e;
		st = strtol(d2+2, &e, 10);
		if(*e || e==d2+2) return 0;
		if(st<0) st = -st;
		if(st==0) st = 1;
	}
	char *e1, *e2;
	long x = strtol(a, &e1, 10), y = strtol(b, &e2, 10);
	if(!*e1 && !*e2) {
		int w = 0;
		const char *aa = a[0]=='-' ? a+1 : a, *bb = b[0]=='-' ? b+1 : b;
		if((aa[0]=='0' && aa[1]) || (bb[0]=='0' && bb[1])) w = (int)(strlen(a)>strlen(b) ? strlen(a) : strlen(b));
		for(long i = x; x<=y ? i<=y : i>=y; i += x<=y ? st : -st) {
			char t[64];
			if(w && i<0) snprintf(t, sizeof(t), "-%0*ld", w-1, -i);
			else snprintf(t, sizeof(t), "%0*ld", w, i);
			sv_push(o, strdup(t));
		}
		return 1;
	}
	if(!a[1] && !b[1] && a[0]>0 && b[0]>0) {
		for(int i = a[0]; a[0]<=b[0] ? i<=b[0] : i>=b[0]; i += a[0]<=b[0] ? st : -st) {
			char t[2] = {(char)i, 0};
			sv_push(o, strdup(t));
		}
		return 1;
	}
	return 0;
}

static void bexp(const char *w, StrV *out) {
	const char *o = strchr(w, 2);
	if(!o) {
		char *r = strdup(w);
		unmark(r);
		sv_push(out, r);
		return;
	}
	int d = 0;
	const char *c = o;
	for(; *c; c++) {
		if(*c==2) d++;
		else if(*c==3 && --d==0) break;
	}
	if(!*c) {
		char *r = strdup(w);
		unmark(r);
		sv_push(out, r);
		return;
	}
	size_t pl = (size_t)(o-w);
	const char *suf = c+1;
	StrV alt = {0};
	d = 0;
	const char *s = o+1;
	int com = 0;
	for(const char *q = o+1; q<c; q++) {
		if(*q==2) d++;
		else if(*q==3) d--;
		else if(*q==4 && d==0) {
			char *t = strndup(s, (size_t)(q-s));
			sv_push(&alt, t);
			s = q+1;
			com = 1;
		}
	}
	if(com) sv_push(&alt, strndup(s, (size_t)(c-s)));
	else {
		char *t = strndup(o+1, (size_t)(c-o-1));
		unmark(t);
		if(!bseq(t, &alt)) {
			Buf b;
			binit(&b);
			bput(&b, w, pl);
			b8(&b, '{');
			bput(&b, t, strlen(t));
			b8(&b, '}');
			bput(&b, suf, strlen(suf));
			char *r = buf_to_cstr(&b);
			bexp(r, out);
			free(r);
			free(t);
			return;
		}
		free(t);
	}
	for(int i = 0; i<alt.n; i++) {
		Buf b;
		binit(&b);
		bput(&b, w, pl);
		bput(&b, alt.v[i], strlen(alt.v[i]));
		bput(&b, suf, strlen(suf));
		char *r = buf_to_cstr(&b);
		bexp(r, out);
		free(r);
		free(alt.v[i]);
	}
	free(alt.v);
}

static int tilde(const char **pp, Buf *buf) {
	const char *p = *pp;
	if(*p!='~') return 0;
	const char *q = p+1;
	while(isnm(*q) || *q=='-' || *q=='.') q++;
	if(*q!='/' && *q!=':' && !is_token_terminator(*q)) return 0;
	char *h = NULL;
	if(q==p+1) h = getenv("HOME");
	else {
		char un[128];
		size_t n = (size_t)(q-p-1);
		if(n>127) n = 127;
		memcpy(un, p+1, n);
		un[n] = '\0';
		struct passwd *pw = getpwnam(un);
		if(pw) h = pw->pw_dir;
	}
	if(!h) return 0;
	bput(buf, h, strlen(h));
	*pp = q;
	return 1;
}

static int g_gq, g_gu;

static char *parse_word(const char **pp) {
	Buf buf;
	binit(&buf);
	g_gq = g_gu = 0;
	const char *p = *pp;
	const char *bst[32];
	int bn = 0, asg = 0;
	tilde(&p, &buf);
	while(*p) {
		if(bn && p==bst[bn-1]) {
			b8(&buf, 3);
			bn--;
			p++;
			continue;
		}
		if(bn && *p==',') {
			b8(&buf, 4);
			p++;
			continue;
		}
		if(*p=='{' && bn<32) {
			const char *e = bval(p);
			if(e) {
				bst[bn++] = e;
				b8(&buf, 2);
				p++;
				continue;
			}
		}
		if(*p=='\\') {
			p++;
			if(*p=='\0') parse_error("trailing escape");
			if(*p=='\n') { p++; continue; }
			if(*p=='*' || *p=='?' || *p=='[') g_gq = 1;
			b8(&buf, (uint8_t)*p++);
			continue;
		}
		if(*p=='"') {
			p++;
			int closed = 0;
			while(*p) {
				if(*p=='"') {
					closed = 1;
					p++;
					break;
				}
				if(*p=='\\') {
					p++;
					if(*p=='\0') parse_error("unterminated escape in quotes");
					char esc = *p++;
					if(esc=='"' || esc=='\\' || esc=='$' || esc=='`') {
						b8(&buf, (uint8_t)esc);
					} else if(esc=='\n') {
					} else {
						b8(&buf, (uint8_t)'\\');
						b8(&buf, (uint8_t)esc);
					}
					continue;
				} else if(*p=='$') {
					p++;
					xdol(&p, &buf, 1);
					continue;
				} else if(*p=='`') {
					p++;
					Buf sc;
					binit(&sc);
					while(*p && *p!='`') b8(&sc, (uint8_t)*p++);
					if(*p=='`') p++;
					char *s = buf_to_cstr(&sc);
					csub(s, &buf);
					free(s);
					continue;
				}
				if(*p=='*' || *p=='?' || *p=='[') g_gq = 1;
				b8(&buf, (uint8_t)*p++);
			}
			if(!closed) parse_error("unterminated double quote");
			continue;
		}
		if(*p=='\'') {
			p++;
			while(*p && *p!='\'') {
				if(*p=='*' || *p=='?' || *p=='[') g_gq = 1;
				b8(&buf, (uint8_t)*p++);
			}
			if(*p!='\'') parse_error("unterminated single quote");
			p++;
			continue;
		}
		if(*p=='`') {
			p++;
			Buf sc;
			binit(&sc);
			while(*p && *p!='`') b8(&sc, (uint8_t)*p++);
			if(*p=='`') p++;
			char *s = buf_to_cstr(&sc);
			csub(s, &buf);
			free(s);
			continue;
		}
		if((*p=='<' || *p=='>') && p[1]=='(') {
			static int g_psub_cnt = 0;
			g_psub_cnt++;
			char ptype = *p;
			p += 2;
			char subcmd[256];
			int ci = 0;
			int depth = 1;
			while(*p && ci < 255) {
				if(*p=='(') depth++;
				else if(*p==')') {
					depth--;
					if(depth==0) { p++; break; }
				}
				subcmd[ci++] = *p++;
			}
			subcmd[ci] = '\0';
			char tfpath[128];
			snprintf(tfpath, sizeof(tfpath), "/tmp/.sh2elf_psub_%d", g_psub_cnt);
			if(ptype == '<') {
				FILE *fp = popen(subcmd, "r");
				if(fp) {
					char cbuf[4096];
					size_t nr = fread(cbuf, 1, sizeof(cbuf)-1, fp);
					cbuf[nr] = '\0';
					pclose(fp);
					FILE *tf = fopen(tfpath, "wb");
					if(tf) {
						fwrite(cbuf, 1, nr, tf);
						fclose(tf);
					}
				}
				bput(&buf, tfpath, strlen(tfpath));
			} else {
				bput(&buf, tfpath, strlen(tfpath));
			}
			continue;
		}
		if(*p=='$') {
			p++;
			xdol(&p, &buf, 0);
			continue;
		}
		if(*p=='~' && asg==1) {
			const char *q = p;
			if(tilde(&q, &buf)) {
				p = q;
				asg = 2;
				continue;
			}
		}
		if(is_token_terminator(*p) && *p!='{' && *p!='}') break;
		if(*p=='*' || *p=='?' || *p=='[') g_gu = 1;
		if(*p=='=' && !asg && buf.len>0 && !bn) {
			asg = 1;
			for(size_t k = 0; k<buf.len; k++) if(!isnm((char)buf.data[k])) asg = 0;
			if(buf.data[0]>='0' && buf.data[0]<='9') asg = 0;
			if(asg) {
				b8(&buf, '=');
				p++;
				continue;
			}
			asg = 0;
		}
		if(*p==':' && asg) {
			b8(&buf, ':');
			p++;
			asg = 1;
			continue;
		}
		if(asg) asg = 2;
		b8(&buf, (uint8_t)*p++);
	}
	if(p == *pp) {
		if(buf.data) free(buf.data);
		return NULL;
	}
	char *word = buf_to_cstr(&buf);
	*pp = p;
	return word;
}

static char *xword(const char *s) {
	const char *p = s;
	Buf b;
	binit(&b);
	while(*p) {
		if(*p=='$') {
			p++;
			xdol(&p, &b, 1);
		} else if(*p=='\\' && p[1]) {
			p++;
			b8(&b, (uint8_t)*p++);
		} else if(*p=='"' || *p=='\'') {
			const char *q = p;
			char *w = parse_word(&q);
			if(w) { bput(&b, w, strlen(w)); free(w); }
			if(q==p) q++;
			p = q;
		} else b8(&b, (uint8_t)*p++);
	}
	return buf_to_cstr(&b);
}

static void penv_restore(Stage *st) {
	for(int i = st->pold.n-1; i>=0; i--) {
		char *e = strchr(st->pold.v[i], '=');
		if(e) {
			*e = 0;
			setenv(st->pold.v[i], e+1, 1);
			*e = '=';
		} else unsetenv(st->pold.v[i]);
		free(st->pold.v[i]);
	}
	free(st->pold.v);
	st->pold = (StrV){0};
}

static const char *penv_skip(const char *q) {
	while(*q && *q!=' ' && *q!='\t' && *q!='\n' && *q!=';' && *q!='&' && *q!='|' && *q!=')') {
		if(*q=='\\' && q[1]) q += 2;
		else if(*q=='\'') {
			q++;
			while(*q && *q!='\'') q++;
			if(*q) q++;
		} else if(*q=='"') {
			q++;
			while(*q && *q!='"') { if(*q=='\\' && q[1]) q++; q++; }
			if(*q) q++;
		} else q++;
	}
	return q;
}

static int penv_cmd(const char *q) {
	for(;;) {
		while(*q==' ' || *q=='\t') q++;
		if(!*q || *q=='\n' || *q==';' || *q=='&' || *q=='|' || *q==')' || *q=='}' || *q=='#') return 0;
		const char *w = q;
		int asg = 0;
		if(isalpha((unsigned char)*w) || *w=='_') {
			while(isalnum((unsigned char)*w) || *w=='_') w++;
			asg = *w=='=';
		}
		if(!asg) return 1;
		q = penv_skip(q);
	}
}

static void finish_stage(Pipeline *pl, Stage *st) {
	if(st->argv.n>0 && st->pold.n) penv_restore(st);
	if(st->argv.n==0) {
		if(st->in_redir || st->out_redir || st->err_redir) parse_error("redirection without command");
		return;
	}
	pl_push(pl, *st);
	*st = (Stage){0};
}

typedef struct {
	char *name;
	char *body;
} FuncDef;

typedef struct {
	FuncDef *v;
	int n, cap;
} FuncTable;

static FuncTable g_funcs = {0};

static Script parse(const char *src);

static char *ltok(const char **pp, const char **ts) {
	const char *p = *pp;
	for(;;) {
		while(*p==' ' || *p=='\t' || *p=='\r' || *p=='\n' || *p==';' || *p=='&' || *p=='|' || *p=='(' || *p==')') p++;
		if(*p=='#') {
			while(*p && *p!='\n') p++;
			continue;
		}
		break;
	}
	if(!*p) {
		*pp = p;
		return NULL;
	}
	*ts = p;
	const char *s = p;
	while(*p && *p!=' ' && *p!='\t' && *p!='\r' && *p!='\n' && *p!=';' && *p!='&' && *p!='|' && *p!='(' && *p!=')') {
		if(*p=='\\' && p[1]) { p += 2; continue; }
		if(*p=='\'' || *p=='"') {
			char e = *p++;
			while(*p && *p!=e) { if(e=='"' && *p=='\\' && p[1]) p++; p++; }
			if(*p) p++;
			continue;
		}
		p++;
	}
	*pp = p;
	return strndup(s, (size_t)(p-s));
}

static const char *lbody(const char *p, const char **bs, const char **be) {
	int d = 1;
	const char *ts;
	*bs = p;
	char *w;
	while((w = ltok(&p, &ts))) {
		if(strcmp(w,"do")==0) d++;
		else if(strcmp(w,"done")==0 && --d==0) {
			*be = ts;
			free(w);
			return p;
		}
		free(w);
	}
	return NULL;
}

static const char *lscan(const char *p, const char **cs, const char **ce, const char **bs, const char **be) {
	const char *ts;
	char *w;
	while(*p==' ' || *p=='\t') p++;
	*cs = p;
	while((w = ltok(&p, &ts))) {
		int dw = strcmp(w,"do")==0;
		free(w);
		if(dw) {
			*ce = ts;
			return lbody(p, bs, be);
		}
	}
	return NULL;
}

typedef struct Tn {
	int k;
	const char *o, *a, *b;
	struct Tn *l, *r;
} Tn;

static char **tv;
static int tn, ti, tx;

static Tn *tnew(int k, const char *o, const char *a, const char *b) {
	Tn *t = (Tn*)calloc(1, sizeof(Tn));
	t->k = k;
	t->o = o;
	t->a = a;
	t->b = b;
	return t;
}

static int tbin(const char *s) {
	static const char *ops[] = {"=", "==", "!=", "<", ">", "-eq", "-ne", "-gt", "-ge", "-lt", "-le", "-nt", "-ot", "-ef", "=~", NULL};
	for(int i = 0; ops[i]; i++) if(strcmp(s, ops[i])==0) return 1;
	return 0;
}

static int tuna(const char *s) {
	return s[0]=='-' && s[1] && !s[2] && strchr("efdsrwxLhpSbcgukOGtzn", s[1]);
}

static Tn *tor(void);

static int tis(const char *s) {
	if(ti>=tn) return 0;
	if(strcmp(tv[ti], s)==0) return 1;
	if(tx && strcmp(s,"-a")==0 && strcmp(tv[ti],"&&")==0) return 1;
	if(tx && strcmp(s,"-o")==0 && strcmp(tv[ti],"||")==0) return 1;
	return 0;
}

static Tn *tprim(void) {
	int rem = tn-ti;
	if(rem<=0) return tnew(0, "1", NULL, NULL);
	if(tis("(") && rem>=3) {
		ti++;
		Tn *e = tor();
		if(tis(")")) ti++;
		return e;
	}
	if(rem>=3 && tbin(tv[ti+1])) {
		Tn *t = tnew(2, tv[ti+1], tv[ti], tv[ti+2]);
		ti += 3;
		return t;
	}
	if(rem>=2 && tuna(tv[ti])) {
		Tn *t = tnew(1, tv[ti], tv[ti+1], NULL);
		ti += 2;
		return t;
	}
	Tn *t = tnew(1, "-n", tv[ti], NULL);
	ti++;
	return t;
}

static Tn *tnot(void) {
	if(tis("!") && tn-ti>1) {
		ti++;
		Tn *t = tnew(3, NULL, NULL, NULL);
		t->l = tnot();
		return t;
	}
	return tprim();
}

static Tn *tand(void) {
	Tn *l = tnot();
	while(tis("-a")) {
		ti++;
		Tn *t = tnew(4, NULL, NULL, NULL);
		t->l = l;
		t->r = tnot();
		l = t;
	}
	return l;
}

static Tn *tor(void) {
	Tn *l = tand();
	while(tis("-o")) {
		ti++;
		Tn *t = tnew(5, NULL, NULL, NULL);
		t->l = l;
		t->r = tand();
		l = t;
	}
	return l;
}

static Tn *tparse(char **v, int n, int ext) {
	tv = v;
	tn = n;
	ti = 0;
	tx = ext;
	if(n==0) return tnew(0, "1", NULL, NULL);
	return tor();
}

static int trt(const char *s) {
	return s && strchr(s, 1)!=NULL;
}

static int tint(const char *s, long *v) {
	char *e;
	while(*s==' ' || *s=='\t') s++;
	if(!*s) return 0;
	*v = strtol(s, &e, 10);
	while(*e==' ' || *e=='\t') e++;
	return *e=='\0';
}

static int tfold(Tn *t) {
	if(t->k==0) return t->o[0]-'0';
	if(t->k==3) {
		int r = tfold(t->l);
		return r<0 ? r : r==2 ? 2 : !r;
	}
	if(t->k==4 || t->k==5) {
		int a = tfold(t->l), b = tfold(t->r);
		if(t->k==4 && (a==1 || b==1) && a!=-1 && b!=-1) return 1;
		if(t->k==5 && (a==0 || b==0) && a!=-1 && b!=-1) return 0;
		if(a<0 || b<0) return -1;
		return t->k==4 ? (a||b) : (a&&b);
	}
	if(t->k==1) {
		if(trt(t->a)) return -1;
		if(strcmp(t->o,"-z")==0) return t->a[0] ? 1 : 0;
		if(strcmp(t->o,"-n")==0) return t->a[0] ? 0 : 1;
		return -1;
	}
	const char *o = t->o;
	if(trt(t->a) || trt(t->b)) return -1;
	if(strcmp(o,"-nt")==0 || strcmp(o,"-ot")==0 || strcmp(o,"-ef")==0) return -1;
	if(o[0]=='-') {
		long x, y;
		if(!tint(t->a, &x) || !tint(t->b, &y)) {
			fprintf(stderr, "sh2elf: test: integer expression expected\n");
			return 2;
		}
		int r = 0;
		if(strcmp(o,"-eq")==0) r = x==y;
		else if(strcmp(o,"-ne")==0) r = x!=y;
		else if(strcmp(o,"-gt")==0) r = x>y;
		else if(strcmp(o,"-ge")==0) r = x>=y;
		else if(strcmp(o,"-lt")==0) r = x<y;
		else if(strcmp(o,"-le")==0) r = x<=y;
		return !r;
	}
	if(strcmp(o,"=~")==0) {
		regex_t re;
		if(regcomp(&re, t->b, REG_EXTENDED|REG_NOSUB)!=0) return 2;
		int r = regexec(&re, t->a, 0, NULL, 0)==0;
		regfree(&re);
		return !r;
	}
	int c = strcmp(t->a, t->b);
	if(tx && (strcmp(o,"==")==0 || strcmp(o,"=")==0)) return fnmatch(t->b, t->a, 0)!=0;
	if(tx && strcmp(o,"!=")==0) return fnmatch(t->b, t->a, 0)==0;
	if(strcmp(o,"=")==0 || strcmp(o,"==")==0) return c!=0;
	if(strcmp(o,"!=")==0) return c==0;
	if(strcmp(o,"<")==0) return !(c<0);
	return !(c>0);
}

static int targs(Stage *st, char ***v, int *n) {
	const char *c0 = st->argv.v[0];
	*v = st->argv.v+1;
	*n = st->argv.n-1;
	if(strcmp(c0,"[")==0 && *n>0 && strcmp((*v)[*n-1],"]")==0) (*n)--;
	if(strcmp(c0,"[[")==0 && *n>0 && strcmp((*v)[*n-1],"]]")==0) (*n)--;
	return strcmp(c0,"[[")==0;
}

static int ctcond(const char *s) {
	while(*s==' ' || *s=='\t' || *s=='\n') s++;
	int neg = 0;
	if(s[0]=='!' && (s[1]==' ' || s[1]=='\t')) {
		neg = 1;
		s++;
		while(*s==' ' || *s=='\t') s++;
	}
	int r = -1;
	if(s[0]=='(' && s[1]=='(') {
		const char *e = mpar(s+2);
		if(!e) return -1;
		char *ex = strndup(s+2, (size_t)(e-(s+2)));
		r = arith(ex)!=0 ? 0 : 1;
		free(ex);
	} else if(s[0]=='[' || strncmp(s, "test", 4)==0) {
		Script cs = parse(s);
		if(cs.n!=1 || cs.v[0].pl.n!=1 || cs.v[0].pl.neg) return -1;
		Stage *st = &cs.v[0].pl.v[0];
		const char *c0 = st->argv.v[0];
		if(strcmp(c0,"[")!=0 && strcmp(c0,"[[")!=0 && strcmp(c0,"test")!=0) return -1;
		char **v;
		int n;
		int ext = targs(st, &v, &n);
		r = tfold(tparse(v, n, ext));
		if(r==2) r = 1;
	}
	if(r<0) return -1;
	return neg ? !r : r;
}

static void gpush(StrV *av, char *word) {
	if(strpbrk(word, "*?[")!=NULL && !(g_gq && !g_gu)) {
		glob_t gbuf = {0};
		if(glob(word, 0, NULL, &gbuf)==0 && gbuf.gl_pathc>0) {
			for(size_t gi=0; gi<gbuf.gl_pathc; gi++) {
				sv_push(av, strdup(gbuf.gl_pathv[gi]));
			}
			free(word);
			globfree(&gbuf);
			return;
		}
		globfree(&gbuf);
	}
	sv_push(av, word);
}

static void scat(Script *sc, Script *sub) {
	for(int si=0; si<sub->n; si++) sc_push(sc, sub->v[si].pl, sub->v[si].cond);
	free(sub->v);
}

static Script parse(const char *src) {
	Script sc = {0};
	Pipeline cur = {0};
	Stage st = {0};
	const char *p = src;
	int pending_cond = COND_ALWAYS;
	int is_until = 0;
	while(*p) {
		skip_inline_ws(&p);
		if(*p=='\0') break;
		if(*p=='#') {
			while(*p && *p!='\n') p++;
			continue;
		}
		if(*p=='(' && p[1]=='(' && st.argv.n==0) {
			const char *e = mpar(p+2);
			if(e) {
				char *ex = strndup(p+2, (size_t)(e-(p+2)));
				long v = arith(ex);
				free(ex);
				sv_push(&st.argv, strdup(v ? "true" : "false"));
				p = e+2;
				continue;
			}
		}
		if(*p=='(' || *p==')' || (*p=='{' && (p[1]==' ' || p[1]=='\t' || p[1]=='\n' || p[1]=='\r' || !p[1])) || *p=='}') {
			p++;
			continue;
		}
		if(*p=='\n' || *p==';') {
			if(st.argv.n>0) {
				finish_stage(&cur, &st);
			} else if(st.in_redir || st.out_redir || st.err_redir) {
				parse_error("redirection without command");
			}
			if(cur.n>0) {
				sc_push(&sc, cur, pending_cond);
				cur = (Pipeline){0};
				pending_cond = COND_ALWAYS;
			}
			while(*p=='\n' || *p==';') p++;
			continue;
		}
		if(*p=='&') {
			if(p[1]=='&') {
				if(st.argv.n>0) finish_stage(&cur, &st);
				if(cur.n>0) {
					sc_push(&sc, cur, pending_cond);
					cur = (Pipeline){0};
				}
				if(sc.n==0) parse_error("missing command before &&");
				pending_cond = COND_PREV_SUCCESS;
				p+=2;
				continue;
			}
			if(st.argv.n>0) finish_stage(&cur, &st);
			if(cur.n==0) parse_error("missing command before &");
			cur.bg = 1;
			sc_push(&sc, cur, pending_cond);
			cur = (Pipeline){0};
			pending_cond = COND_ALWAYS;
			p++;
			continue;
		}
		if(*p=='|') {
			if(p[1]=='|') {
				if(st.argv.n>0) finish_stage(&cur, &st);
				if(cur.n>0) {
					sc_push(&sc, cur, pending_cond);
					cur = (Pipeline){0};
				}
				if(sc.n==0) parse_error("missing command before ||");
				pending_cond = COND_PREV_FAILURE;
				p+=2;
				continue;
			}
			if(st.argv.n>0) {
				finish_stage(&cur, &st);
			} else if(cur.n==0 && sc.n>0) {
				cur = sc.v[--sc.n].pl;
			} else if(cur.n==0) {
				parse_error("empty pipeline stage");
			}
			p++;
			continue;
		}
		if(((*p=='>' && p[1]!='(') || (*p=='<' && p[1]!='(')) || (*p=='2' && p[1]=='>')) {
			int is_err = (*p=='2');
			if(is_err) p++;
			char op = *p++;
			int append = 0;
			if(op=='<' && *p=='<' && p[1]=='<') {
				p += 2;
				skip_inline_ws(&p);
				char *w = parse_word(&p);
				if(!w) parse_error("missing here-string word");
				unmark(w);
				size_t n = strlen(w);
				char *h = (char*)malloc(n+2);
				memcpy(h, w, n);
				h[n] = '\n';
				h[n+1] = '\0';
				free(w);
				if(st.hstr) free(st.hstr);
				st.hstr = h;
				continue;
			}
			if(op=='<' && *p=='<') {
				p++;
				if(*p=='-') p++;
				skip_inline_ws(&p);
				char *delim = parse_word(&p);
				if(!delim) parse_error("missing heredoc delimiter");
				while(*p && *p!='\n') p++;
				if(*p=='\n') p++;
				Buf hbuf;
				binit(&hbuf);
				while(*p) {
					const char *lstart = p;
					while(*p && *p!='\n') p++;
					size_t llen = (size_t)(p - lstart);
					if(*p=='\n') p++;
					char lbuf[256];
					if(llen >= sizeof(lbuf)) llen = sizeof(lbuf)-1;
					memcpy(lbuf, lstart, llen);
					lbuf[llen] = '\0';
					if(strcmp(lbuf, delim)==0) break;
					bput(&hbuf, lstart, llen);
					b8(&hbuf, '\n');
				}
				FILE *hf = fopen("/tmp/.sh2elf_hdoc", "wb");
				if(hf) {
					fwrite(hbuf.data, 1, hbuf.len, hf);
					fclose(hf);
				}
				free(hbuf.data);
				free(delim);
				if(st.in_redir) free(st.in_redir);
				st.in_redir = strdup("/tmp/.sh2elf_hdoc");
				continue;
			}
			if(op=='>' && *p=='>') {
				append = 1;
				p++;
			}
			char *target = NULL;
			skip_inline_ws(&p);
			if(*p=='&') {
				p++;
				if(*p=='-') {
					p++;
					target = strdup("&-");
				} else if(*p>='0' && *p<='9') {
					const char *tstart = p;
					while(*p>='0' && *p<='9') p++;
					size_t tlen = (size_t)(p - tstart);
					target = (char*)malloc(tlen + 2);
					target[0] = '&';
					memcpy(target + 1, tstart, tlen);
					target[tlen + 1] = '\0';
				}
			}
			if(!target) {
				if(*p=='\0' || *p=='\n' || *p=='|' || *p==';' || (*p=='<' && p[1]!='(') || (*p=='>' && p[1]!='(')) parse_error("missing redirection target");
				target = parse_word(&p);
				if(!target) parse_error("missing redirection target");
				unmark(target);
			}
			if(op=='<') {
				if(st.in_redir) free(st.in_redir);
				st.in_redir = target;
			} else if(is_err) {
				if(st.err_redir) free(st.err_redir);
				st.err_redir = target;
				st.err_append = append;
			} else {
				if(st.out_redir) free(st.out_redir);
				st.out_redir = target;
				st.out_append = append;
			}
			continue;
		}
		char *word = parse_word(&p);
		if(!word) { p++; continue; }
		if(st.argv.n==0) {
			if(strcmp(word,"!")==0 && cur.n==0) {
				cur.neg = !cur.neg;
				free(word);
				continue;
			}
			if(strcmp(word,"[[")==0) {
				sv_push(&st.argv, word);
				for(;;) {
					skip_inline_ws(&p);
					if(!*p || *p=='\n') parse_error("missing ]]");
					if(p[0]==']' && p[1]==']') {
						p += 2;
						sv_push(&st.argv, strdup("]]"));
						break;
					}
					if((p[0]=='&' && p[1]=='&') || (p[0]=='|' && p[1]=='|')) {
						sv_push(&st.argv, strndup(p, 2));
						p += 2;
						continue;
					}
					if(*p=='(' || *p==')' || *p=='<' || *p=='>') {
						sv_push(&st.argv, strndup(p, 1));
						p++;
						continue;
					}
					if(strcmp(st.argv.v[st.argv.n-1],"=~")==0 && *p!='"' && *p!='\'') {
						const char *q = p;
						int d = 0;
						while(*q && *q!='\n' && !(d==0 && (*q==' ' || *q=='\t' || (q[0]==']' && q[1]==']')))) {
							if(*q=='(') d++;
							else if(*q==')') d--;
							q++;
						}
						sv_push(&st.argv, strndup(p, (size_t)(q-p)));
						p = q;
						continue;
					}
					char *w = parse_word(&p);
					if(!w) { p++; continue; }
					unmark(w);
					sv_push(&st.argv, w);
				}
				continue;
			}
			if(strcmp(word,"local")==0 || strcmp(word,"export")==0) {
				sv_push(&st.argv, strdup(word));
				skip_inline_ws(&p);
				char *arg = parse_word(&p);
				if(arg) {
					char *eq = strchr(arg, '=');
					if(eq) {
						*eq = '\0';
						setenv(arg, eq + 1, 1);
						*eq = '=';
					}
					sv_push(&st.argv, arg);
				}
				free(word);
				continue;
			}
			if(strcmp(word,"return")==0) {
				sv_push(&st.argv, strdup(word));
				skip_inline_ws(&p);
				char *arg = parse_word(&p);
				if(arg) {
					sv_push(&st.argv, arg);
				}
				finish_stage(&cur, &st);
				sc_push(&sc, cur, pending_cond);
				cur = (Pipeline){0};
				pending_cond = COND_ALWAYS;
				free(word);
				break;
			}
			int is_fn_call = 0;
			for(int fi=0; fi<g_funcs.n; fi++) {
				if(strcmp(word, g_funcs.v[fi].name)==0) {
					is_fn_call = 1;
					StrV fa = {0};
					for(;;) {
						skip_inline_ws(&p);
						if(!*p || strchr("\n;|&)<>}", *p)) break;
						char *a = parse_word(&p);
						if(!a) break;
						if(strchr(a, 2)) {
							bexp(a, &fa);
							free(a);
						} else sv_push(&fa, a);
					}
					char **sa = g_fa;
					int sn = g_fn;
					g_fa = fa.v;
					g_fn = fa.n;
					g_fdep++;
					Script sub = parse(g_funcs.v[fi].body);
					g_fdep--;
					g_fa = sa;
					g_fn = sn;
					for(int k = 0; k<fa.n; k++) free(fa.v[k]);
					free(fa.v);
					for(int si=0; si<sub.n; si++) {
						sc_push(&sc, sub.v[si].pl, sub.v[si].cond);
					}
					free(sub.v);
					free(word);
					break;
				}
			}
			if(is_fn_call) continue;
			if(strstr(word, "()")!=NULL || (*p=='(' && p[1]==')')) {
				char *fname = strdup(word);
				char *paren = strstr(fname, "()");
				if(paren) *paren = '\0';
				else {
					if(*p=='(' && p[1]==')') p += 2;
				}
				skip_inline_ws(&p);
				if(*p=='{') {
					p++;
					const char *fstart = p;
					int depth = 1;
					const char *fend = NULL;
					while(*p) {
						if(*p=='{') depth++;
						else if(*p=='}') {
							depth--;
							if(depth==0) {
								fend = p;
								p++;
								break;
							}
						}
						p++;
					}
					if(fend) {
						size_t flen = (size_t)(fend - fstart);
						char *fbody = (char*)malloc(flen + 1);
						memcpy(fbody, fstart, flen);
						fbody[flen] = '\0';
						if(g_funcs.n==g_funcs.cap) {
							g_funcs.cap = g_funcs.cap ? g_funcs.cap*2 : 8;
							g_funcs.v = (FuncDef*)realloc(g_funcs.v, g_funcs.cap*sizeof(FuncDef));
						}
						g_funcs.v[g_funcs.n++] = (FuncDef){ fname, fbody };
						free(word);
						continue;
					}
				}
				free(fname);
			}
			if(strcmp(word,"case")==0) {
				free(word);
				skip_inline_ws(&p);
				char *targ = parse_word(&p);
				if(!targ) parse_error("expected case target");
				skip_inline_ws(&p);
				const char *tp0 = p;
				char *w0 = parse_word(&tp0);
				if(w0) {
					if(strcmp(w0,"in")==0) p = tp0;
					free(w0);
				}
				int matched = 0;
				while(*p) {
					while(*p=='\n' || *p==';' || *p==' ') p++;
					skip_inline_ws(&p);
					if(*p=='\0') break;
					const char *tp = p;
					char *pw = parse_word(&tp);
					if(pw) {
						if(strcmp(pw,"esac")==0) {
							free(pw);
							p = tp;
							break;
						}
						free(pw);
					}
					if(*p=='(') {
						p++;
						skip_inline_ws(&p);
					}
					char *pat = parse_word(&p);
					if(!pat) break;
					if(strcmp(pat,"esac")==0) {
						free(pat);
						break;
					}
					StrV alts = {0};
					sv_push(&alts, pat);
					skip_inline_ws(&p);
					while(*p=='|') {
						p++;
						skip_inline_ws(&p);
						char *a = parse_word(&p);
						if(a) sv_push(&alts, a);
						skip_inline_ws(&p);
					}
					while(*p && *p!=')') p++;
					if(*p==')') p++;
					const char *cstart = p;
					const char *cend = NULL;
					while(*p) {
						if(*p=='\'' || *p=='"') {
							char e = *p++;
							while(*p && *p!=e) {
								if(e=='"' && *p=='\\' && p[1]) p++;
								p++;
							}
							if(*p) p++;
							continue;
						}
						if(*p=='\\' && p[1]) {
							p += 2;
							continue;
						}
						if(p[0]==';' && p[1]==';') {
							cend = p;
							p += 2;
							break;
						}
						if(strncmp(p, "esac", 4)==0 && is_token_terminator(p[4]) && (p==cstart || strchr(" \t\n;", p[-1]))) {
							cend = p;
							break;
						}
						p++;
					}
					if(!cend) cend = p;
					int hit = 0;
					for(int k = 0; k<alts.n && !hit; k++) {
						unmark(alts.v[k]);
						hit = strcmp(alts.v[k],"*")==0 || strcmp(alts.v[k],targ)==0 || fnmatch(alts.v[k],targ,0)==0;
					}
					if(!matched && targ && hit) {
						matched = 1;
						size_t clen = (size_t)(cend - cstart);
						char *cbody = (char*)malloc(clen + 1);
						memcpy(cbody, cstart, clen);
						cbody[clen] = '\0';
						Script sub = parse(cbody);
						for(int si=0; si<sub.n; si++) {
							sc_push(&sc, sub.v[si].pl, sub.v[si].cond);
						}
						free(sub.v);
						free(cbody);
					}
					for(int k = 0; k<alts.n; k++) free(alts.v[k]);
					free(alts.v);
				}
				if(targ) free(targ);
				continue;
			}
			if(strcmp(word,"while")==0 || strcmp(word,"until")==0) {
				const char *cs, *ce, *bs, *be;
				const char *le = lscan(p, &cs, &ce, &bs, &be);
				if(le) {
					int un = word[0]=='u';
					char *ct = strndup(cs, (size_t)(ce-cs));
					char *bt = strndup(bs, (size_t)(be-bs));
					int it = 0, r;
					while((r = ctcond(ct))>=0 && (un ? r!=0 : r==0)) {
						if(++it>100000) parse_error("loop exceeds compile-time unroll limit");
						Script sub = parse(bt);
						scat(&sc, &sub);
					}
					free(ct);
					free(bt);
					if(r>=0 || it>0) {
						free(word);
						pending_cond = COND_ALWAYS;
						p = le;
						continue;
					}
				}
			}
			if(strcmp(word,"if")==0 || strcmp(word,"while")==0 || strcmp(word,"case")==0) {
				pending_cond = COND_ALWAYS;
				free(word);
				continue;
			}
			if(strcmp(word,"until")==0) {
				pending_cond = COND_ALWAYS;
				is_until = 1;
				free(word);
				continue;
			}
			if(strcmp(word,"then")==0 || strcmp(word,"do")==0) {
				if(st.argv.n>0) finish_stage(&cur, &st);
				if(cur.n>0) { sc_push(&sc, cur, pending_cond); cur = (Pipeline){0}; }
				pending_cond = is_until ? COND_PREV_FAILURE : COND_PREV_SUCCESS;
				is_until = 0;
				free(word);
				continue;
			}
			if(strcmp(word,"else")==0 || strcmp(word,"elif")==0) {
				if(st.argv.n>0) finish_stage(&cur, &st);
				if(cur.n>0) { sc_push(&sc, cur, pending_cond); cur = (Pipeline){0}; }
				pending_cond = COND_PREV_FAILURE;
				free(word);
				continue;
			}
			if(strcmp(word,"fi")==0 || strcmp(word,"done")==0) {
				if(st.argv.n>0) finish_stage(&cur, &st);
				if(cur.n>0) { sc_push(&sc, cur, pending_cond); cur = (Pipeline){0}; }
				pending_cond = COND_ALWAYS;
				free(word);
				continue;
			}
			if(strcmp(word,"for")==0) {
				pending_cond = COND_ALWAYS;
				free(word);
				skip_inline_ws(&p);
				if(p[0]=='(' && p[1]=='(') {
					const char *e = mpar(p+2);
					if(!e) parse_error("unterminated for ((");
					char *ex = strndup(p+2, (size_t)(e-(p+2)));
					char *s1 = ex, *s2 = NULL, *s3 = NULL;
					int d = 0;
					for(char *q = ex; *q; q++) {
						if(*q=='(') d++;
						else if(*q==')') d--;
						else if(*q==';' && d==0) {
							*q = '\0';
							if(!s2) s2 = q+1;
							else if(!s3) s3 = q+1;
						}
					}
					if(!s3) parse_error("malformed for (( ))");
					p = e+2;
					while(*p==' ' || *p=='\t' || *p==';' || *p=='\n' || *p=='\r') p++;
					if(strncmp(p, "do", 2)!=0) parse_error("expected do");
					const char *bs, *be;
					const char *le = lbody(p+2, &bs, &be);
					if(!le) parse_error("missing done");
					char *bt = strndup(bs, (size_t)(be-bs));
					int it = 0;
					arith(s1);
					for(;;) {
						const char *t = s2;
						while(*t==' ' || *t=='\t') t++;
						if(*t && arith(s2)==0) break;
						if(++it>100000) parse_error("loop exceeds compile-time unroll limit");
						Script sub = parse(bt);
						scat(&sc, &sub);
						arith(s3);
					}
					free(bt);
					free(ex);
					p = le;
					continue;
				}
				char *vname = parse_word(&p);
				if(!vname) parse_error("expected for variable");
				skip_inline_ws(&p);
				const char *tp0 = p;
				char *w0 = parse_word(&tp0);
				if(w0) {
					if(strcmp(w0,"in")==0) p = tp0;
					free(w0);
				}
				StrV items = {0};
				while(*p) {
					skip_inline_ws(&p);
					if(*p==';' || *p=='\n' || *p=='\0') break;
					const char *tp = p;
					char *w = parse_word(&tp);
					if(!w) break;
					if(strcmp(w,"do")==0) {
						free(w);
						break;
					}
					char *ifs = getenv("IFS");
					StrV bw = {0};
					bexp(w, &bw);
					free(w);
					for(int bi = 0; bi<bw.n; bi++) {
						w = bw.v[bi];
						if(ifs && *ifs) {
							char *wcopy = strdup(w);
							char *tok = strtok(wcopy, ifs);
							while(tok) {
								sv_push(&items, strdup(tok));
								tok = strtok(NULL, ifs);
							}
							free(wcopy);
							free(w);
						} else {
							gpush(&items, w);
						}
					}
					free(bw.v);
					p = tp;
				}
				while(*p==';' || *p=='\n' || *p==' ') p++;
				const char *tp1 = p;
				char *w1 = parse_word(&tp1);
				if(w1) {
					if(strcmp(w1,"do")==0) p = tp1;
					free(w1);
				}
				skip_inline_ws(&p);
				const char *bstart = p;
				int depth = 1;
				const char *scan = p;
				const char *bend = NULL;
				while(*scan) {
					skip_inline_ws(&scan);
					if(*scan=='\0') break;
					if(*scan=='#' || *scan=='\n' || *scan==';') { scan++; continue; }
					const char *tp = scan;
					char *w = parse_ident(&scan);
					if(w) {
						if(strcmp(w,"do")==0) depth++;
						else if(strcmp(w,"done")==0) {
							depth--;
							if(depth==0) {
								bend = tp;
								free(w);
								break;
							}
						}
						free(w);
					} else scan++;
				}
				if(!bend) parse_error("missing done");
				size_t blen = (size_t)(bend - bstart);
				char *body = (char*)malloc(blen + 1);
				memcpy(body, bstart, blen);
				body[blen] = '\0';
				for(int ki=0; ki<items.n; ki++) {
					setenv(vname, items.v[ki], 1);
					Script sub = parse(body);
					for(int si=0; si<sub.n; si++) {
						sc_push(&sc, sub.v[si].pl, sub.v[si].cond);
					}
					free(sub.v);
				}
				free(body);
				free(vname);
				for(int ki=0; ki<items.n; ki++) free(items.v[ki]);
				free(items.v);
				p = scan;
				continue;
			}
			if(strcmp(word,"if")==0 || strcmp(word,"in")==0 || strcmp(word,"while")==0 || strcmp(word,"until")==0) {
				free(word);
				continue;
			}
			if(strchr(word, '=')!=NULL && word!=strchr(word, '=')) {
				unmark(word);
				char *eq = strchr(word, '=');
				*eq = '\0';
				if(penv_cmd(p)) {
					const char *ov = getenv(word);
					char *o;
					if(ov) {
						o = malloc(strlen(word)+strlen(ov)+2);
						sprintf(o, "%s=%s", word, ov);
					} else o = strdup(word);
					sv_push(&st.pold, o);
					*eq = '=';
					sv_push(&st.penv, strdup(word));
					*eq = '\0';
				}
				setenv(word, eq+1, 1);
				free(word);
				continue;
			}
		}
		if(st.argv.n>0 && strcmp(st.argv.v[0],"export")==0 && strchr(word, '=')!=NULL) {
			char *eq = strchr(word, '=');
			*eq = '\0';
			setenv(word, eq+1, 1);
			*eq = '=';
		}
		if(strchr(word, 2)) {
			StrV bw = {0};
			bexp(word, &bw);
			free(word);
			for(int bi = 0; bi<bw.n; bi++) gpush(&st.argv, bw.v[bi]);
			free(bw.v);
			continue;
		}
		gpush(&st.argv, word);
	}
	if(st.argv.n>0) {
		finish_stage(&cur, &st);
	} else if(st.in_redir || st.out_redir || st.err_redir) {
		parse_error("redirection without command");
	}
	if(cur.n>0) sc_push(&sc, cur, pending_cond);
	return sc;
}

typedef struct {
	Code code;
	StrPool strs;
	Rels rels;
	size_t bss_base;
	size_t bss_off;
	size_t status_off;
	size_t sp_off, bg_off, scr_off, tb_off, out_off, wt_pos, ct_pos, ct_pg, ct_pl, ct_rs, ct_by, ct_p0, lz_t, lz_a, lw_top, lw_pg, le_tab;
	int lz_n, lz_u;
	char *lz_z;
	int wt_n;
	size_t *cr;
	size_t ncr, ccr;
	size_t *xa;
	const char **xn;
	int nx, cx, rtok;
} Gen;

static size_t add_str(Gen *g, const char *s) {
	return sp_add(&g->strs, s);
}

static void rels_add_here(Gen *g, size_t at, size_t sidx) {
	if(g->rels.n==g->rels.cap) {
		g->rels.cap=g->rels.cap?g->rels.cap*2:64;
		g->rels.v=(Rel*)realloc(g->rels.v, g->rels.cap*sizeof(Rel));
	}
	g->rels.v[g->rels.n++] = (Rel) {
		at, sidx
	};
}

#undef mov_rdi_str
#undef mov_rsi_str
static void mov_rdi_str(Code *c, Gen *g, size_t sidx) {
	c8(c,0x48);
	c8(c,0xBF);
	size_t at=cpos(c);
	uint64_t z=0;
	bput(&c->code,&z,8);
	rels_add_here(g, at, sidx);
}

static void mov_rsi_str(Code *c, Gen *g, size_t sidx) {
	c8(c,0x48);
	c8(c,0xBE);
	size_t at=cpos(c);
	uint64_t z=0;
	bput(&c->code,&z,8);
	rels_add_here(g, at, sidx);
}

static void write_literal(Code *c, Gen *g, const char *s) {
	size_t sidx = add_str(g, s);
	mov_rsi_str(c,g,sidx);
	mov_rdi_imm64(c,1);
	mov_rdx_imm64(c, strlen(s));
	sys_write(c);
}

static void build_argv(Code *c, Gen *g, size_t bss_off, size_t *sidxv, int argc) {
	uint64_t base = g->bss_base + bss_off;
	mov_rdi_imm64(c, base);
	for(int i=0; i<argc; i++) {
		c8(c,0x48);
		c8(c,0xB8);
		size_t at=cpos(c);
		uint64_t z=0;
		bput(&c->code,&z,8);
		rels_add_here(g, at, sidxv[i]);
		mov_m8_rdi_disp32_rax(c, (uint32_t)(i*8));
	}
	mov_rax_imm32(c,0);
	mov_m8_rdi_disp32_rax(c, (uint32_t)(argc*8));
	mov_rsi_rdi(c);
}

static int emit_dup(Code *c, const char *t, int fd) {
	if(t[0]!='&') return 0;
	if(t[1]=='-') {
		mov_rdi_imm64(c, (uint64_t)fd);
		sys_close(c);
		return 1;
	}
	mov_rdi_imm64(c, (uint64_t)atoi(t+1));
	mov_rsi_imm64(c, (uint64_t)fd);
	sys_dup2(c);
	return 1;
}

static void emit_redirs(Code *c, Gen *g, const char *in_redir, const char *out_redir, int append, const char *err_redir, int err_append) {
	if(in_redir && !emit_dup(c, in_redir, 0)) {
		size_t sidx = add_str(g, in_redir);
		mov_rdi_imm64(c, (uint64_t)-100);
		mov_rsi_str(c,g,sidx);
		mov_rdx_imm64(c, 0);
		xor_r10_r10(c);
		sys_openat(c);
		mov_rdi_rax(c);
		c8(c,0x49); c8(c,0x89); c8(c,0xC0);
		mov_rsi_imm64(c, 0);
		sys_dup2(c);
		c8(c,0x4C); c8(c,0x89); c8(c,0xC7);
		sys_close(c);
	}
	if(out_redir && !emit_dup(c, out_redir, 1)) {
		size_t sidx = add_str(g, out_redir);
		int flags = 1 | 64 | (append?1024:512);
		mov_rdi_imm64(c, (uint64_t)-100);
		mov_rsi_str(c,g,sidx);
		mov_rdx_imm64(c, (uint64_t)flags);
		mov_r10_imm64(c, 0666);
		sys_openat(c);
		mov_rdi_rax(c);
		c8(c,0x49); c8(c,0x89); c8(c,0xC0);
		mov_rsi_imm64(c, 1);
		sys_dup2(c);
		c8(c,0x4C); c8(c,0x89); c8(c,0xC7);
		sys_close(c);
	}
	if(err_redir && !emit_dup(c, err_redir, 2)) {
		size_t sidx = add_str(g, err_redir);
		int flags = 1 | 64 | (err_append?1024:512);
		mov_rdi_imm64(c, (uint64_t)-100);
		mov_rsi_str(c,g,sidx);
		mov_rdx_imm64(c, (uint64_t)flags);
		mov_r10_imm64(c, 0666);
		sys_openat(c);
		mov_rdi_rax(c);
		c8(c,0x49); c8(c,0x89); c8(c,0xC0);
		mov_rsi_imm64(c, 2);
		sys_dup2(c);
		c8(c,0x4C); c8(c,0x89); c8(c,0xC7);
		sys_close(c);
	}
}

static uint64_t status_addr(Gen *g) {
	return g->bss_base + g->status_off;
}

static void store_status_imm(Code *c, Gen *g, uint32_t val) {
	mov_rax_imm32(c,val);
	mov_rdi_imm64(c, status_addr(g));
	mov_m8_rdi_disp32_rax(c,0);
}

static void store_status_from_wait(Code *c, Gen *g) {
	mov_rdi_imm64(c, status_addr(g));
	mov_eax_mrdi(c);
	shr_rax_imm8(c,8);
	and_eax_imm32(c,0xFF);
	mov_rdi_imm64(c, status_addr(g));
	mov_m8_rdi_disp32_rax(c,0);
}

static void load_status_eax(Code *c, Gen *g) {
	mov_rdi_imm64(c, status_addr(g));
	mov_eax_mrdi(c);
}

static void store_status_rax(Code *c, Gen *g) {
	mov_rdi_imm64(c, status_addr(g));
	mov_m8_rdi_disp32_rax(c,0);
}

static int rtnk(char k) {
	return k=='?' || k=='$' || k=='P' || k=='R' || k=='!' || k=='#';
}

static void rtval(Code *c, Gen *g, char k) {
	if(k=='?') {
		load_status_eax(c,g);
		return;
	}
	if(k=='$' || k=='P') {
		mov_rax_imm32(c, k=='$' ? 39 : 110);
		syscall_(c);
		return;
	}
	if(k=='!') {
		mov_rdi_imm64(c, g->bss_base + g->bg_off);
		c8(c,0x48); c8(c,0x8B); c8(c,0x07);
		return;
	}
	if(k=='R') {
		c8(c,0x48); c8(c,0xBF); c64(c,g->bss_base+g->scr_off);
		c8(c,0xBE); c8(c,0x02); c8(c,0x00); c8(c,0x00); c8(c,0x00);
		c8(c,0x31); c8(c,0xD2);
		c8(c,0xB8); c8(c,0x3E); c8(c,0x01); c8(c,0x00); c8(c,0x00);
		c8(c,0x0F); c8(c,0x05);
		c8(c,0x0F); c8(c,0xB7); c8(c,0x07);
		c8(c,0x25); c8(c,0xFF); c8(c,0x7F); c8(c,0x00); c8(c,0x00);
		return;
	}
	c8(c,0x48); c8(c,0xBF); c64(c,g->bss_base+g->sp_off);
	c8(c,0x48); c8(c,0x8B); c8(c,0x3F);
	c8(c,0x48); c8(c,0x8B); c8(c,0x07);
	c8(c,0x48); c8(c,0xFF); c8(c,0xC8);
}

