	size_t rp = tdata(c, r, sizeof(*r)*(size_t)(rn ? rn : 1));
	size_t op = tdata(c, ob, odl ? odl : 1);
	lrip(c, 0, rp);
	lrip(c, 2, op);
	c8(c,0x48); c8(c,0xBF); c64(c,LB_BASE+0x180000);
	c8(c,0x48); c8(c,0x89); c8(c,0x07);
