	c8(c,0x48); c8(c,0x89); c8(c,0x47); c8(c,0x08);
	c8(c,0x48); c8(c,0xB8); c64(c,(uint64_t)dw);
	c8(c,0x48); c8(c,0x89); c8(c,0x47); c8(c,0x10);
	c8(c,0x48); c8(c,0xB8); c64(c,(uint64_t)dlen);
	c8(c,0x48); c8(c,0x89); c8(c,0x47); c8(c,0x18);
	c8(c,0x48); c8(c,0xB8); c64(c,(uint64_t)odl);
	c8(c,0x48); c8(c,0x89); c8(c,0x47); c8(c,0x28);
	c8(c,0x48); c8(c,0xB8); c64(c,(uint64_t)fl);
	c8(c,0x48); c8(c,0x89); c8(c,0x47); c8(c,0x30);
	c8(c,0x48); c8(c,0xC7); c8(c,0x47); c8(c,0x38); c8(c,0x0A); c8(c,0x00); c8(c,0x00); c8(c,0x00);
	c8(c,0x48); c8(c,0xB8); c64(c,IN_BASE);
	c8(c,0x48); c8(c,0x89); c8(c,0x87); c8(c,0x88); c8(c,0x00); c8(c,0x00); c8(c,0x00);
	c8(c,0x48); c8(c,0xB8); c64(c,g->bss_base+g->out_off);
