static int u8enc(uint32_t c, char *o) {
	if(c<0x80) {
		o[0] = (char)c;
		return 1;
	}
	if(c<0x800) {
		o[0] = (char)(0xC0 | c>>6);
		o[1] = (char)(0x80 | (c & 63));
		return 2;
	}
	if(c<0x10000) {
		o[0] = (char)(0xE0 | c>>12);
		o[1] = (char)(0x80 | ((c>>6) & 63));
		o[2] = (char)(0x80 | (c & 63));
		return 3;
	}
	o[0] = (char)(0xF0 | c>>18);
	o[1] = (char)(0x80 | ((c>>12) & 63));
	o[2] = (char)(0x80 | ((c>>6) & 63));
	o[3] = (char)(0x80 | (c & 63));
	return 4;
}

static const int32_t *g_ct, *g_ci;
static const unsigned char *g_cx;

static int32_t cfind(const unsigned char **cpp) {
	int32_t i = g_ct[*(*cpp)++];
	if(i>=0) return i;
	const unsigned char *cp = &g_cx[-i], *us = *cpp;
	for(;;) {
		i = *(const int32_t*)cp;
		cp += 4;
		size_t nh = *cp++, k;
		if(i>=0) {
			for(k = 0; k<nh; k++) if(cp[k]!=us[k]) break;
			if(k==nh) {
				*cpp += nh;
				return i;
			}
			cp += nh;
			if((1+nh)%4) cp += 4-(1+nh)%4;
			continue;
		}
		size_t off = 0;
		for(k = 0; k<nh; k++) if(cp[k]!=us[k]) break;
		if(k!=nh) {
			int skip = cp[k]>us[k];
			if(!skip) {
				for(k = 0; k<nh; k++) if(cp[nh+k]!=us[k]) break;
				skip = k!=nh && cp[nh+k]<us[k];
			}
			if(skip) {
				cp += 2*nh;
				if((1+2*nh)%4) cp += 4-(1+2*nh)%4;
				continue;
			}
			for(k = 0; cp[k]==us[k]; k++);
			do {
				off <<= 8;
				off += (size_t)(us[k]-cp[k]);
			} while(++k<nh);
		}
		*cpp += nh;
		return g_ci[-i+(int32_t)off];
	}
}

