static uint32_t cleb(const uint8_t **pp) {
	uint32_t v = 0;
	int s = 0;
	const uint8_t *p = *pp;
	for(;;) {
		v |= (uint32_t)(*p & 127)<<s;
		s += 7;
		if(!(*p++ & 128)) break;
	}
	*pp = p;
	return v;
}

static int32_t czz(const uint8_t **pp) {
	uint32_t v = cleb(pp);
	return (int32_t)(v>>1)^-(int32_t)(v & 1);
}

static int cwdec(const uint8_t *b, int n, uint32_t *v) {
	int k = 0;
	for(int i = 0; i<n; ) {
		uint8_t c = b[i];
		int l = c<0x80 ? 1 : c<0xE0 ? 2 : c<0xF0 ? 3 : c<0xF8 ? 4 : c<0xFC ? 5 : 6;
		uint32_t x = l==1 ? c : (uint32_t)(c & (0x7F>>l));
		for(int j = 1; j<l; j++) x = x<<6 | (b[i+j] & 63);
		v[k++] = x;
		i += l;
	}
	return k;
}

static int cwenc(const uint32_t *v, int k, uint8_t *o) {
	int n = 0;
	for(int i = 0; i<k; i++) {
		uint32_t x = v[i];
		int l = x<0x80 ? 1 : x<0x800 ? 2 : x<0x10000 ? 3 : x<0x200000 ? 4 : x<0x4000000 ? 5 : 6;
		if(l==1) {
			o[n++] = (uint8_t)x;
			continue;
		}
		for(int j = l-1; j>0; j--) {
			o[n+j] = (uint8_t)(0x80 | (x & 63));
			x >>= 6;
		}
		o[n] = (uint8_t)((0xFF00>>l) | x);
		n += l;
	}
	return n;
}

static uint8_t *cxraw(uint8_t *w, const uint8_t **pp) {
	const uint8_t *q = *pp;
	*w++ = *q++;
	for(int l = 0; l<4; l++) {
		int n = *q;
		for(int j = 0; j<=n; j++) *w++ = *q++;
	}
	*pp = q;
	return w;
}

static uint8_t *cxap(uint8_t *w, const uint8_t *p, int op, const uint8_t **pay) {
	const uint8_t *y = *pay;
	*w++ = *p++;
	for(int l = 0; l<4; l++) {
		int m = (op>>(2*l)) & 3, n = *p;
		if(m==0) {
			for(int j = 0; j<=n; j++) *w++ = *p++;
		} else if(m==2) {
			p += n+1;
			int k = *y;
			for(int j = 0; j<=k; j++) *w++ = *y++;
		} else {
			uint32_t v[64];
			int k = cwdec(p+1, n, v);
			p += n+1;
			v[k-1] += (uint32_t)czz(&y);
			w[0] = (uint8_t)cwenc(v, k, w+1);
			w += 1+w[0];
		}
	}
	*pay = y;
	return w;
}

static void colxc(const uint8_t *st, uint8_t *mem, uint64_t *P) {
	uint16_t *top = (uint16_t*)mem;
	uint8_t *pg = mem+0x2200;
	uint32_t np = cleb(&st);
	uint8_t *pool = pg+(size_t)np*1024, *w = pool, *prev = pool;
	const uint8_t *rec = NULL;
	uint32_t u = 0, nxp = 1;
	P[0] = (uint64_t)(uintptr_t)top;
	P[1] = (uint64_t)(uintptr_t)pg;
	P[2] = (uint64_t)(uintptr_t)pool;
	w = cxraw(w, &st);
	for(;;) {
		u += cleb(&st)+1;
		int op = *st++;
		if(op==0xFD) break;
		uint32_t rep = 1;
		if(op==0xFE) rep = cleb(&st);
		for(uint32_t r = 0; r<rep; r++) {
			if(r) u++;
			uint8_t *e = w;
			if(op==0xFF) w = cxraw(w, &st);
			else if(op==0xFE) {
				const uint8_t *y = rec+1;
				w = cxap(w, prev, *rec, &y);
			} else {
				rec = st-1;
				w = cxap(w, prev, op, &st);
			}
			prev = e;
			uint32_t hi = u>>8;
			if(!top[hi]) top[hi] = (uint16_t)nxp++;
			((uint32_t*)(pg+(size_t)top[hi]*1024))[u & 255] = (uint32_t)(e-pool);
		}
	}
	P[87] = (uint64_t)(uintptr_t)(pg+(size_t)top[0]*1024);
}

typedef struct {
	uint32_t c, n, v;
	int32_t d;
} CSR;

static int csqdec(const uint8_t *s, CSR **out) {
	int n = 0, cap = 1024;
	CSR *r = malloc(sizeof(CSR)*(size_t)cap);
	uint32_t c = 0, pv = 0;
	for(;;) {
		uint32_t h = cleb(&s);
		if(!h) break;
		uint32_t len = h>>1;
		if(h & 1) {
			c += len;
			continue;
		}
		uint32_t v0 = pv+(uint32_t)czz(&s);
		int32_t d = czz(&s);
		if(n==cap) {
			cap *= 2;
			r = realloc(r, sizeof(CSR)*(size_t)cap);
		}
		r[n].c = c;
		r[n].n = len;
		r[n].v = v0;
		r[n].d = d;
		n++;
		c += len;
		pv = v0+(uint32_t)d*(len-1);
	}
	*out = r;
	return n;
}

static uint32_t csqget(const CSR *r, int n, uint32_t c) {
	int lo = 0, hi = n-1;
	while(lo<=hi) {
		int m = (lo+hi)/2;
		if(c<r[m].c) hi = m-1;
		else if(c>=r[m].c+r[m].n) lo = m+1;
		else return r[m].v+(uint32_t)r[m].d*(c-r[m].c);
	}
	return ~0u;
}

