static const char sou[] = "usage: sort [-m] [-o output] [-bdfinru] [-t char] [-k keydef]... [file...]\n       sort [-c|-C] [-bdfinru] [-t char] [-k keydef] [file]\n";

typedef struct {
	uint64_t sw, sc, ew, ec, fl, ty, p1, p2;
} SKey;

typedef struct {
	SKey *ks;
	int nk, nka;
	uint64_t gfl, gty;
	int ck, ckq, mg, un;
	const char *outf, *tab;
	char **fv;
	int nf;
	char tb[8];
	size_t tl;
	char m[1200];
	uint64_t v[140];
	void *p[140];
	size_t ps[140];
} SO;

static int sopt(char ch, uint64_t *fl, uint64_t *ty) {
	switch(ch) {
	case 'b': *fl |= 3; return 1;
	case 'd': *fl |= 4; return 1;
	case 'i': *fl |= 8; return 1;
	case 'f': *fl |= 16; return 1;
	case 'r': *fl |= 32; return 1;
	case 'n': *fl |= 1<<8; *ty = 1; return 1;
	}
	return 0;
}

static int sinc(SO *o, uint64_t fl) {
	if(!((fl>>8) & 1) || !(fl & 12)) return 1;
	char *p = o->m;
	p += snprintf(p, 64, "sort: options -");
	if(fl & 4) *p++ = 'd';
	if(fl & 16) *p++ = 'f';
	if(fl & 8) *p++ = 'i';
	*p++ = 'n';
	snprintf(p, 64, " are incompatible\n");
	return 0;
}

static const char *snum(const char *p, uint64_t *v) {
	if(*p<'0' || *p>'9') return NULL;
	uint64_t n = 0;
	for(; *p>='0' && *p<='9'; p++) n = n>(UINT64_MAX-9)/10 ? UINT64_MAX : n*10+(uint64_t)(*p-'0');
	*v = n;
	return p;
}

static int skparse(SO *o, const char *s) {
	SKey k;
	memset(&k, 0, sizeof(k));
	k.ew = (uint64_t)-1;
	uint64_t v;
	const char *p = snum(s, &v);
	if(!p) {
		snprintf(o->m, sizeof(o->m), "sort: invalid number at field start: invalid count at start of %s\n", s);
		return 0;
	}
	if(!v) {
		snprintf(o->m, sizeof(o->m), "sort: field number is zero: invalid field specification %s\n", s);
		return 0;
	}
	k.sw = v-1;
	if(*p=='.') {
		const char *q = snum(p+1, &v);
		if(!q) {
			snprintf(o->m, sizeof(o->m), "sort: invalid number after '.': invalid count at start of %s\n", p+1);
			return 0;
		}
		if(!v) {
			snprintf(o->m, sizeof(o->m), "sort: character offset is zero: invalid field specification %s\n", s);
			return 0;
		}
		k.sc = v-1;
		p = q;
	}
	uint64_t ty = 0, fl = 0;
	for(; *p && *p!=','; p++) {
		uint64_t f2 = 0;
		if(!sopt(*p, &f2, &ty)) break;
		fl |= f2 & ~(uint64_t)2;
	}
	if(*p==',') {
		const char *q = snum(p+1, &v);
		if(!q) {
			snprintf(o->m, sizeof(o->m), "sort: invalid number after ',': invalid count at start of %s\n", p+1);
			return 0;
		}
		if(!v) {
			snprintf(o->m, sizeof(o->m), "sort: field number is zero: invalid field specification %s\n", s);
			return 0;
		}
		k.ew = v-1;
		p = q;
		if(*p=='.') {
			q = snum(p+1, &k.ec);
			if(!q) {
				snprintf(o->m, sizeof(o->m), "sort: invalid number after '.': invalid count at start of %s\n", p+1);
				return 0;
			}
			p = q;
		}
		for(; *p; p++) {
			uint64_t f2 = 0;
			if(!sopt(*p, &f2, &ty)) break;
			if(*p=='b') f2 = 2;
			fl |= f2;
		}
	}
	if(*p) {
		snprintf(o->m, sizeof(o->m), "sort: stray character in field spec: invalid field specification %s\n", s);
		return 0;
	}
	k.fl = fl;
	k.ty = ty;
	if(o->nk==o->nka) {
		o->nka = o->nka ? o->nka*2 : 8;
		o->ks = realloc(o->ks, sizeof(SKey)*(size_t)o->nka);
	}
	o->ks[o->nk++] = k;
	return 1;
}

static int sortopt(SO *o, int argc, char **argv) {
	int i = 1;
	o->m[0] = '\0';
	for(; i<argc; i++) {
		char *a = argv[i];
		if(a[0]!='-' || !a[1]) break;
		if(strcmp(a, "--")==0) {
			i++;
			break;
		}
		for(char *q = a+1; *q; q++) {
			char ch = *q;
			if(sopt(ch, &o->gfl, &o->gty)) continue;
			if(ch=='c' || ch=='C' || ch=='m' || ch=='u') {
				if(ch=='c') o->ck = 1;
				else if(ch=='C') o->ckq = 1;
				else if(ch=='m') o->mg = 1;
				else o->un = 1;
				continue;
			}
			if(ch=='k' || ch=='o' || ch=='t') {
				char *val = q[1] ? q+1 : i+1<argc ? argv[++i] : NULL;
				if(!val) {
					snprintf(o->m, sizeof(o->m), "sort: option requires an argument -- '%c'\n", ch);
					return 0;
				}
				if(ch=='k') {
					if(!skparse(o, val)) return 0;
				} else if(ch=='o') {
					if(o->outf && strcmp(o->outf, val)!=0) {
						snprintf(o->m, sizeof(o->m), "sort: multiple output files specified\n");
						return 0;
					}
					o->outf = val;
				} else {
					if(o->tab && strcmp(o->tab, val)!=0) {
						snprintf(o->m, sizeof(o->m), "sort: incompatible tabs\n");
						return 0;
					}
					o->tab = val;
				}
				break;
			}
			snprintf(o->m, sizeof(o->m), "sort: invalid option -- '%c'\n", ch);
			return 0;
		}
	}
	o->fv = argv+i;
	o->nf = argc-i;
	if(o->tab) {
		unsigned char t0 = (unsigned char)o->tab[0];
		size_t cl = t0<0x80 ? 1 : t0>=0xF0 ? 4 : t0>=0xE0 ? 3 : t0>=0xC0 ? 2 : 1;
		if(!t0) {
			snprintf(o->m, sizeof(o->m), "sort: empty tab\n");
			return 0;
		}
		if(strlen(o->tab)!=cl) {
			snprintf(o->m, sizeof(o->m), "sort: multi-character tab %s\n", o->tab);
			return 0;
		}
		memcpy(o->tb, o->tab, cl);
		o->tl = cl;
	}
	if(o->ck && o->ckq) {
		snprintf(o->m, sizeof(o->m), "sort: options -cC are incompatible\n");
		return 0;
	}
	if((o->ck || o->ckq) && o->outf) {
		snprintf(o->m, sizeof(o->m), "sort: options -%co are incompatible\n", o->ckq ? 'C' : 'c');
		return 0;
	}
	if((o->ck || o->ckq) && o->nf>1) {
		snprintf(o->m, sizeof(o->m), "sort: extra operand %s not allowed with -%c\n", o->fv[1], o->ckq ? 'C' : 'c');
		return 0;
	}
	if(o->gfl & 4) o->gfl &= ~(uint64_t)8;
	for(int k = 0; k<o->nk; k++) {
		if(!o->ks[k].fl && !o->ks[k].ty) {
			o->ks[k].fl = o->gfl;
			o->ks[k].ty = o->gty;
		}
		if(o->ks[k].fl & 4) o->ks[k].fl &= ~(uint64_t)8;
		if(!sinc(o, o->ks[k].fl)) return 0;
	}
	return sinc(o, o->gfl);
}

static void ssv(SO *o, int off, uint64_t v) {
	o->v[off/8] = v;
}

static void ssp(SO *o, int off, void *p, size_t n) {
	o->p[off/8] = p;
	o->ps[off/8] = n;
}

static void srng(SO *o, int off, uint8_t *bm) {
	uint32_t *r = malloc(8*4096), n = 0, cap = 4096, lo = 0;
	int in = 0;
	for(uint32_t u = 0; u<=0x110000; u++) {
		int x = u<0x110000 && (bm[u>>3]>>(u & 7) & 1);
		if(x && !in) {
			lo = u;
			in = 1;
		} else if(!x && in) {
			if(n==cap) {
				cap *= 2;
				r = realloc(r, 8*(size_t)cap);
			}
			r[2*n] = lo;
			r[2*n+1] = u-1;
			n++;
			in = 0;
		}
	}
	ssp(o, off, r, 8*(size_t)(n ? n : 1));
	ssv(o, off+8, n);
}

static void supr(SO *o, int off) {
	uint32_t *r = malloc(16*1024), n = 0, cap = 1024, lo = 0, base = 0, kind = 0, last = 0;
	int have = 0;
	for(uint32_t u = 0x80; u<=0x110000; u++) {
		uint32_t t = u;
		if(u<0x110000 && !(u>=0xD800 && u<=0xDFFF)) t = trcase(u, 1, 1);
		if(u<0x110000 && t==u) continue;
		if(u<0x110000 && have && u==last+1) {
			uint32_t pt = kind==1 ? base+(last-lo) : base;
			if(kind!=1 && t==pt && (kind==0 || u==lo+1)) {
				kind = 0;
				last = u;
				continue;
			}
			if((kind==1 || u==lo+1) && t==pt+1 && !(kind==0 && u!=lo+1)) {
				kind = 1;
				last = u;
				continue;
			}
		}
		if(have) {
			if(n==cap) {
				cap *= 2;
				r = realloc(r, 16*(size_t)cap);
			}
			r[4*n] = lo;
			r[4*n+1] = last;
			r[4*n+2] = base;
			r[4*n+3] = kind==1 ? 1 : 0;
			n++;
		}
		if(u==0x110000) break;
		have = 1;
		lo = last = u;
		base = t;
		kind = 2;
	}
	ssp(o, off, r, 16*(size_t)(n ? n : 1));
	ssv(o, off+8, n);
}

static void sortmk(SO *o) {
	int pure = !o->nk && !(o->gfl & ~(uint64_t)32);
	if(!o->nk && !pure) {
		o->ks = realloc(o->ks, sizeof(SKey));
		memset(o->ks, 0, sizeof(SKey));
		o->ks[0].ew = (uint64_t)-1;
		o->ks[0].fl = o->gfl;
		o->ks[0].ty = o->gty;
		o->nk = 1;
	}
	int nd = 0, ni = 0, nfu = 0;
	for(int k = 0; k<o->nk; k++) {
		if(o->ks[k].fl & 4) nd = 1;
		if(o->ks[k].fl & 8) ni = 1;
		if(o->ks[k].fl & 16) nfu = 1;
		o->ks[k].fl &= 63;
	}
	if(o->nk) {
		SKey *kc = malloc(sizeof(SKey)*(size_t)o->nk);
		memcpy(kc, o->ks, sizeof(SKey)*(size_t)o->nk);
		ssp(o, 24, kc, sizeof(SKey)*(size_t)o->nk);
	}
	ssv(o, 32, (uint64_t)o->nk);
	ssv(o, 40, (o->gfl & 32 ? 1 : 0) | (o->un ? 2 : 0) | (o->ck || o->ckq ? 8 : 0) | (o->ckq ? 16 : 0) | (o->mg ? 32 : 0) | (pure ? 64 : 384));
	uint64_t tw = 0;
	memcpy(&tw, o->tb, 8);
	ssv(o, 48, tw);
	ssv(o, 56, o->tl);
	ssv(o, 88, '\n');
	if(nd || ni) {
		TrX *x = calloc(1, sizeof(TrX));
		if(nd) srng(o, 160, trbm(x, 0));
		if(ni) srng(o, 176, trbm(x, 7));
		for(int i = 0; i<12; i++) free(x->bm[i]);
		free(x);
	}
	if(nfu) supr(o, 192);
}

static void sofree(SO *o) {
	for(int i = 0; i<140; i++) free(o->p[i]);
	free(o->ks);
}

