static void tool_ln(Code *c, Gen *g, Stage *st, int us) {
	uint64_t fl;
	char **fv;
	int nf;
	char m[4200];
	if(!lnopt(st->argv.n, st->argv.v, &fl, &fv, &nf, m, sizeof(m))) {
		wlit2(c,g,m);
		if(us) store_status_imm(c,g,1);
		return;
	}
	tini(c,g);
	const char *dir = fv[nf-1];
	if(nf==2) {
		char *d2 = lnjoin(dir, fv[0]);
		lncall(c, g, fv[0], dir, d2, fl | 8, NULL);
		free(d2);
	} else {
		size_t ab = 0;
		lncall(c, g, "", dir, dir, 32, &ab);
		for(int i = 0; i<nf-1; i++) {
			char *d = lnjoin(dir, fv[i]);
			lncall(c, g, fv[i], d, d, fl, NULL);
			free(d);
		}
		patch_here(c,ab);
	}
	tend(c,g,us);
}

