enum { XO_SOPT = 3, XO_ENV };

typedef struct { int t; long v; char *s; int rc; } XOp;

typedef struct {
	XOp *op;
	int nop, cop, stop;
	int mode, delim, lpe, ape, xit, pcmd, qry, arun;
	const char *eofs, *rep;
	char em[512];
} XS;

static void xop(XS *x, int t, long v, char *s, int rc) {
	if(x->nop==x->cop) {
		x->cop = x->cop ? x->cop*2 : 16;
		x->op = realloc(x->op, sizeof(XOp)*(size_t)x->cop);
	}
	x->op[x->nop].t = t;
	x->op[x->nop].v = v;
	x->op[x->nop].s = s;
	x->op[x->nop].rc = rc;
	x->nop++;
}

static char *xfmt(const char *fmt, ...) {
	char *m;
	va_list ap;
	va_start(ap, fmt);
	if(vasprintf(&m, fmt, ap)<0) m = strdup("");
	va_end(ap);
	return m;
}

static const char g_xus[] = "usage: xargs [-prtx] [-E eofstr|-0] [-I replstr|-L number|-n number] [-s size] [utility [argument...]]\n";

static long xnum(XS *x, const char *s, int opt) {
	long v = 0;
	const char *p = s;
	if(!*p) goto bad;
	for(; *p; p++) {
		if(*p<'0' || *p>'9') goto bad;
		if(v>(LONG_MAX-9)/10) v = LONG_MAX/10;
		v = v*10+(*p-'0');
	}
	if(v<1) goto bad;
	return v;
bad:
	snprintf(x->em, sizeof(x->em), "xargs: -%c: invalid argument: %s\n%s", opt, s, g_xus);
	x->stop = 1;
	return 0;
}

static int xparse(XS *x, int argc, char **argv) {
	int i = 1;
	for(; i<argc && !x->stop; i++) {
		char *a = argv[i];
		if(a[0]!='-' || !a[1]) break;
		if(strcmp(a, "--")==0) { i++; break; }
		for(char *q = a+1; *q && !x->stop; q++) {
			if(!strchr("0EILnprstx", *q)) {
				snprintf(x->em, sizeof(x->em), "xargs: invalid option -- '%c'\n%s", *q, g_xus);
				x->stop = 1;
				break;
			}
			const char *oa = NULL;
			if(strchr("EILns", *q)) {
				if(q[1]) oa = q+1;
				else if(i+1<argc) oa = argv[++i];
				else {
					snprintf(x->em, sizeof(x->em), "xargs: option requires an argument -- '%c'\n%s", *q, g_xus);
					x->stop = 1;
					break;
				}
			}
			switch(*q) {
			case '0': x->mode = 1; x->delim = 0; break;
			case 'E': x->eofs = *oa ? oa : NULL; break;
			case 'I': x->rep = oa; x->lpe = x->ape = 0; break;
			case 'L': x->lpe = (int)xnum(x, oa, 'L'); x->ape = 0; x->rep = NULL; break;
			case 'n': x->ape = (int)xnum(x, oa, 'n'); x->lpe = 0; x->rep = NULL; break;
			case 's': xop(x, XO_SOPT, xnum(x, oa, 's'), NULL, 0); break;
			case 'p': x->qry = 1; x->pcmd = 1; break;
			case 'r': x->arun = 0; break;
			case 't': x->pcmd = 1; break;
			case 'x': x->xit = 1; break;
			}
			if(oa) break;
		}
	}
	if(!x->stop) xop(x, XO_ENV, 0, NULL, 0);
	return i;
}

