typedef struct { int t; char *s; int rc; } COp;

typedef struct {
	COp *op;
	int nop, cop, stop, u8, split;
	uint64_t fl;
	int deref, inter, sparse, reflink, update, btype, rene, raw;
	const char *suffix, *tdir, *pn;
} CS;

static void cop(CS *x, int t, char *s, int rc) {
	if(x->nop==x->cop) {
		x->cop = x->cop ? x->cop*2 : 16;
		x->op = realloc(x->op, sizeof(COp)*(size_t)x->cop);
	}
	x->op[x->nop].t = t;
	x->op[x->nop].s = s;
	x->op[x->nop].rc = rc;
	x->nop++;
}

static void cerr(CS *x, char *m) {
	cop(x, CO_ERR, m, 0);
}

static void cxconf(Buf *b, uint64_t *off, uint64_t *n) {
	*off = b->len;
	*n = 0;
	FILE *f = fopen("/etc/xattr.conf", "r");
	if(!f) return;
	Buf t;
	binit(&t);
	char tmp[4096];
	size_t k;
	while((k = fread(tmp, 1, sizeof(tmp), f))>0) bput(&t, tmp, k);
	fclose(f);
	b8(&t, 0);
	char *s = (char*)t.data;
	char *pat[4096];
	int act[4096], np = 0;
	for(;;) {
		s += strspn(s, " \t\n");
		size_t l = strcspn(s, " \t\n#");
		if(s[l]=='#') {
			if(l) { np = 0; break; }
			s += strcspn(s, "\n");
			continue;
		} else if(s[l]==0) break;
		else if(s[l]=='\n') { np = 0; break; }
		char *p = strndup(s, l);
		s += l;
		s += strspn(s, " \t");
		l = strcspn(s, " \t\n#");
		int a;
		if(l==4 && !strncmp(s, "skip", 4)) a = 1;
		else if(l==11 && !strncmp(s, "permissions", 11)) a = 2;
		else { free(p); np = 0; break; }
		s += l;
		s += strspn(s, " \t");
		if(*s!='#' && *s!='\n') { free(p); np = 0; break; }
		if(np<4096) { pat[np] = p; act[np] = a; np++; }
		s += strcspn(s, "\n");
	}
	free(t.data);
	uint64_t base = b->len;
	uint8_t z[16];
	memset(z, 0, sizeof(z));
	for(int i = 0; i<np; i++) bput(b, z, 16);
	for(int i = 0; i<np; i++) {
		uint64_t r[2] = {(uint64_t)act[np-1-i], b->len};
		bput(b, pat[np-1-i], strlen(pat[np-1-i])+1);
		memcpy(b->data+base+16*(size_t)i, r, 16);
		free(pat[np-1-i]);
	}
	*n = (uint64_t)np;
}

