static const char g_mvus[] = "usage: mv [-if] source_file target_file\n       mv [-if] source_file... target_dir\n";

static void mvusage(CS *x, char *m) {
	cerr(x, m);
	cop(x, CO_ERR, xfmt("%s", g_mvus), 0);
	cop(x, CO_EXIT, NULL, 1);
	x->stop = 1;
}

static int mvparse(CS *x, int argc, char **argv) {
	int i = 1;
	for(; i<argc && !x->stop; i++) {
		char *a = argv[i];
		if(a[0]!='-' || !a[1]) break;
		if(strcmp(a, "--")==0) { i++; break; }
		for(char *q = a+1; *q; q++) {
			if(*q=='f') x->inter = 1;
			else if(*q=='i') x->inter = 3;
			else {
				mvusage(x, xfmt("mv: invalid option -- '%c'\n", *q));
				return i;
			}
		}
	}
	return i;
}

static void tool_mv(Code *c, Gen *g, Stage *st, int us) {
	CS X;
	memset(&X, 0, sizeof(X));
	CS *x = &X;
	char *olc = setlocale(LC_ALL, NULL);
	char *svl = olc ? strdup(olc) : NULL;
	if(!setlocale(LC_ALL, "")) setlocale(LC_ALL, "C");
	x->pn = "mv";
	x->rene = -1;
	x->raw = 1;
	x->u8 = MB_CUR_MAX>1;
	x->fl = CF_MOVE|CF_POWN|CF_PLNK|CF_PMOD|CF_PTS|CF_PXA|CF_REC|CF_DATA;
	x->deref = 2;
	x->sparse = 2;
	x->reflink = 1;
	x->suffix = "~";
	int argc = st->argv.n;
	char **argv = st->argv.v;
	int oi = mvparse(x, argc, argv);
	int nf = argc-oi;
	char **fv = argv+oi;
	if(!x->stop && nf<2) {
		if(nf<=0) mvusage(x, xfmt("mv: missing file operand\n"));
		else mvusage(x, xfmt("mv: missing destination file operand after %s\n", fv[0]));
	}
	if(x->stop) nf = 0;
	x->split = x->nop;
	cpemit(c, g, us, x, nf, fv);
	for(int i = 0; i<x->nop; i++) if(x->op[i].t!=CO_OUT) free(x->op[i].s);
	free(x->op);
	setlocale(LC_ALL, svl ? svl : "C");
	free(svl);
}
enum { RF_F = 1, RF_R = 2, RF_D = 4, RF_PROOT = 16, RF_V = 128 };

static const char g_rmus[] = "usage: rm [-diRrv] file...\n       rm -f [-diRrv] [file...]\n";

static void rmusage(CS *x, char *m) {
	cerr(x, m);
	cop(x, CO_ERR, xfmt("%s", g_rmus), 0);
	cop(x, CO_EXIT, NULL, 1);
	x->stop = 1;
}

static int rparse(CS *x, int argc, char **argv, int *rin) {
	int i = 1;
	*rin = 1;
	x->fl |= RF_PROOT;
	for(; i<argc && !x->stop; i++) {
		char *a = argv[i];
		if(a[0]!='-' || !a[1]) break;
		if(strcmp(a, "--")==0) { i++; break; }
		for(char *q = a+1; *q; q++) {
			switch(*q) {
			case 'd': x->fl |= RF_D; break;
			case 'f': *rin = 0; x->fl |= RF_F; break;
			case 'i': *rin = 2; x->fl &= ~(uint64_t)RF_F; break;
			case 'r': case 'R': x->fl |= RF_R; break;
			case 'v': x->fl |= RF_V; break;
			default:
				rmusage(x, xfmt("rm: invalid option -- '%c'\n", *q));
				return i;
			}
		}
	}
	return i;
}

