	c8(c,0x4C); c8(c,0x89); c8(c,0xA3); c8(c,0x28); c8(c,0x30); c8(c,0x00); c8(c,0x00);
	c8(c,0x4C); c8(c,0x89); c8(c,0xAB); c8(c,0x30); c8(c,0x30); c8(c,0x00); c8(c,0x00);
	c8(c,0x4C); c8(c,0x89); c8(c,0xB3); c8(c,0x38); c8(c,0x30); c8(c,0x00); c8(c,0x00);
