	for(; oi<argc && !x->stop; oi++) {
		char *a = argv[oi];
		if(a[0]!='-' || !a[1]) break;
		if(strcmp(a, "--")==0) { oi++; break; }
		for(char *q = a+1; *q && !x->stop; q++) {
			if(*q=='a') ch |= 1;
			else if(*q=='m') ch |= 2;
			else if(*q=='c') fl |= TF_NOCR;
			else if(*q=='r' || *q=='t' || *q=='d') {
				const char *oa;
				if(q[1]) oa = q+1;
				else if(oi+1<argc) oa = argv[++oi];
				else { tusage(x, xfmt("touch: option requires an argument -- '%c'\n", *q)); break; }
				nsrc++;
				if(*q=='r') { fl |= TF_REF; ref = oa; }
				else if(*q=='t') {
					time_t tt;
					if(!tptime(&tt, oa, 4|8)) tusage(x, xfmt("touch: -t: invalid time: %s\n", oa));
					else { tset = tt; fl |= TF_TSET; }
				} else {
					if(!tiso(oa, &dcs, &dcn)) tusage(x, xfmt("touch: -d: invalid date_time: %s\n", oa));
					else fl |= TF_DATE;
				}
				break;
			} else tusage(x, xfmt("touch: invalid option -- '%c'\n", *q));
		}
	}
	if(!x->stop && nsrc>1) tusage(x, xfmt("touch: cannot specify times from more than one source\n"));
	if(!ch) ch = 3;
	fl |= (uint64_t)ch;
