enum { CW_R = 1, CW_LOG = 16, CW_COM = 32, CW_AREF = 128, CW_OWN = 1024 };

static void cwusage(CS *x, int own, char *m) {
	cerr(x, m);
	cop(x, CO_ERR, xfmt(own ? "usage: chown [-h] owner[:group] file...\n       chown -R [-H|-L|-P] owner[:group] file...\n" : "usage: chgrp [-h] group file...\n       chgrp -R [-H|-L|-P] group file...\n"), 0);
	cop(x, CO_EXIT, NULL, 1);
	x->stop = 1;
}

