typedef struct {
	char **n, **v;
	int c, cap;
} Cm;

static int cmi(Cm *m, const char *n) {
	for(int i = 0; i<m->c; i++) if(strcmp(m->n[i], n)==0) return i;
	return -1;
}

static void cmset(Cm *m, const char *n, const char *v) {
	int i = cmi(m, n);
	if(i<0) {
		if(m->c==m->cap) {
			m->cap = m->cap ? m->cap*2 : 32;
			m->n = realloc(m->n, sizeof(char*)*(size_t)m->cap);
			m->v = realloc(m->v, sizeof(char*)*(size_t)m->cap);
		}
		i = m->c++;
		m->n[i] = strdup(n);
		m->v[i] = NULL;
	}
	free(m->v[i]);
	m->v[i] = v ? strdup(v) : NULL;
}

static const char *cmget(Cm *m, const char *n) {
	int i = cmi(m, n);
	return i<0 ? NULL : m->v[i];
}

static Cm cmdup(Cm *m) {
	Cm r = {0};
	for(int i = 0; i<m->c; i++) cmset(&r, m->n[i], m->v[i]);
	return r;
}

static void cmfree(Cm *m) {
	for(int i = 0; i<m->c; i++) {
		free(m->n[i]);
		free(m->v[i]);
	}
	free(m->n);
	free(m->v);
	*m = (Cm){0};
}

static void cmclear(Cm *m) {
	for(int i = 0; i<m->c; i++) {
		free(m->v[i]);
		m->v[i] = NULL;
	}
}

