static int hkcat0(Buf *b, Wd *w) {
	for(int i = 0; i<w->n; i++) {
		Wp *p = &w->p[i];
		if(p->k==WP_DQ) {
			if(!hkcat0(b, p->dq[0])) return 0;
		} else if(p->k==WP_LIT || p->k==WP_SQ) bput(b, p->s, strlen(p->s));
		else return 0;
	}
	return 1;
}

static char *hkstr0(Wd *w) {
	Buf b;
	binit(&b);
	if(!hkcat0(&b, w)) {
		free(b.data);
		return NULL;
	}
	return buf_to_cstr(&b);
}

typedef struct {
	Buf t, q;
	int bad, anyq;
} Fw;

static void fwput(Fw *f, const char *s, int q) {
	for(; *s; s++) {
		b8(&f->t, (uint8_t)*s);
		b8(&f->q, (uint8_t)q);
	}
}

