static char *csguess(An *c) {
	if(!c || c->k!=N_LIST || c->n!=1) return NULL;
	An *a = c->v[0];
	if(a->k!=N_SIMPLE || a->nas || a->nrd || !a->nw) return NULL;
	char *n0 = hkstr0(a->w[0]);
	int ok = n0!=NULL;
	for(int i = 0; ok && g_csok[i]; i++) if(strcmp(g_csok[i], n0)==0) ok = 2;
	free(n0);
	if(ok!=2) return NULL;
	Buf cmd;
	binit(&cmd);
	for(int i = 0; i<a->nw; i++) {
		char *x = hkstr0(a->w[i]);
		if(!x) {
			free(cmd.data);
			return NULL;
		}
		b8(&cmd, '\'');
		for(char *p = x; *p; p++) {
			if(*p=='\'') bput(&cmd, "'\\''", 4);
			else b8(&cmd, (uint8_t)*p);
		}
		bput(&cmd, "' ", 2);
		free(x);
	}
	bput(&cmd, "2>/dev/null", 11);
	char *cs = buf_to_cstr(&cmd);
	Buf o;
	binit(&o);
	csub(cs, &o);
	free(cs);
	return buf_to_cstr(&o);
}

static void fwword(Fw *f, Wd *w, int dq, Cm *m) {
	for(int i = 0; i<w->n && !f->bad; i++) {
		Wp *p = &w->p[i];
		switch(p->k) {
		case WP_LIT: fwput(f, p->s, dq ? 1 : 0); break;
		case WP_SQ:
			fwput(f, p->s, 1);
			f->anyq = 1;
			break;
		case WP_DQ:
			f->anyq = 1;
			fwword(f, p->dq[0], 1, m);
			break;
		case WP_CMD: {
			char *v = csguess(p->cmd);
			if(!v) {
				f->bad = 1;
				break;
			}
			fwput(f, v, dq ? 1 : 2);
			free(v);
			break;
		}
		case WP_PAR: {
			if(p->op || (p->fl & (PF_LEN | PF_IND)) || !(isalpha((unsigned char)p->s[0]) || p->s[0]=='_')) {
				f->bad = 1;
				break;
			}
			const char *v = cmget(m, p->s);
			if(!v) {
				f->bad = 1;
				break;
			}
			fwput(f, v, dq ? 1 : 2);
			break;
		}
		default:
			f->bad = 1;
		}
	}
}

static int fwfields(Wd *w, Cm *m, StrV *out) {
	Fw f = {0};
	binit(&f.t);
	binit(&f.q);
	fwword(&f, w, 0, m);
	if(f.bad) {
		free(f.t.data);
		free(f.q.data);
		return 0;
	}
	Buf cur;
	binit(&cur);
	int have = f.anyq;
	for(size_t i = 0; i<f.t.len; i++) {
		char c = (char)f.t.data[i];
		if(f.q.data[i]==2 && (c==' ' || c=='\t' || c=='\n')) {
			if(cur.len || have) {
				sv_push(out, buf_to_cstr(&cur));
				binit(&cur);
			}
			have = 0;
			continue;
		}
		b8(&cur, (uint8_t)c);
		have = 1;
	}
	if(cur.len || have) sv_push(out, buf_to_cstr(&cur));
	else free(cur.data);
	free(f.t.data);
	free(f.q.data);
	return 1;
}

static char *fwstr(Wd *w, Cm *m) {
	Fw f = {0};
	binit(&f.t);
	binit(&f.q);
	fwword(&f, w, 1, m);
	free(f.q.data);
	if(f.bad) {
		free(f.t.data);
		return NULL;
	}
	return buf_to_cstr(&f.t);
}

static void crel(Gen *g, size_t at, size_t t) {
	if(g->ncr==g->ccr) {
		g->ccr = g->ccr ? g->ccr*2 : 1024;
		g->cr = realloc(g->cr, sizeof(size_t)*2*g->ccr);
	}
	g->cr[2*g->ncr] = at;
	g->cr[2*g->ncr+1] = t;
	g->ncr++;
}

static size_t gen_hook(Gen *g, StrV *av, An *a, Cm *m) {
	Code *c = &g->code;
	size_t pos = cpos(c);
	c8(c,0x53); c8(c,0x55);
	c8(c,0x41); c8(c,0x54);
	c8(c,0x41); c8(c,0x55);
	c8(c,0x41); c8(c,0x56);
	c8(c,0x41); c8(c,0x57);
	c8(c,0x48); c8(c,0x83); c8(c,0xEC); c8(c,0x08);
	Stage st = {0};
	for(int i = 0; i<av->n; i++) sv_push(&st.argv, strdup(av->v[i]));
	int na = a->nas/2;
	char **ov = na ? calloc((size_t)na, sizeof(char*)) : NULL;
	for(int i = 0; i<na; i++) {
		const char *n = a->as[2*i]->raw;
		const char *o = getenv(n);
		ov[i] = o ? strdup(o) : NULL;
		char *v = fwstr(a->as[2*i+1], m);
		setenv(n, v ? v : "", 1);
		free(v);
	}
	if(na) tzset();
	emit_builtin(c, g, &st, 1);
	for(int i = 0; i<na; i++) {
		const char *n = a->as[2*i]->raw;
		if(ov[i]) setenv(n, ov[i], 1);
		else unsetenv(n);
		free(ov[i]);
	}
	free(ov);
	if(na) tzset();
	load_status_eax(c, g);
	c8(c,0x48); c8(c,0x83); c8(c,0xC4); c8(c,0x08);
	c8(c,0x41); c8(c,0x5F);
	c8(c,0x41); c8(c,0x5E);
	c8(c,0x41); c8(c,0x5D);
	c8(c,0x41); c8(c,0x5C);
	c8(c,0x5D); c8(c,0x5B);
	c8(c,0xC3);
	return pos;
}

typedef struct {
	size_t fn;
	StrV av;
} Hk;

typedef struct {
	Hk *v;
	int n, cap;
} Hkg;

typedef struct {
	Hkg *v;
	int n, cap;
	Gen *g;
	long budget;
} Hks;

static void hkwalk(An *a, Hks *h, Cm *m);

static void hkarith(const char *ex, Cm *m) {
	if(!ex) return;
	int asg = 0;
	for(const char *p = ex; *p; p++) {
		if((p[0]=='+' && p[1]=='+') || (p[0]=='-' && p[1]=='-')) asg = 1;
		if(p[0]=='=' && p[1]!='=' && (p==ex || !strchr("=!<>", p[-1]))) asg = 1;
	}
	if(!asg) return;
	for(const char *p = ex; *p;) {
		if(isalpha((unsigned char)*p) || *p=='_') {
			const char *s = p;
			while(isalnum((unsigned char)*p) || *p=='_') p++;
			char *n = strndup(s, (size_t)(p-s));
			cmset(m, n, NULL);
			free(n);
		} else p++;
	}
}

static void hkwd(Wd *w, Hks *h, Cm *m) {
	if(!w) return;
	for(int i = 0; i<w->n; i++) {
		Wp *p = &w->p[i];
		if(p->cmd) {
			Cm s = cmdup(m);
			hkwalk(p->cmd, h, &s);
			cmfree(&s);
		}
		if(p->k==WP_PAR && p->op && (p->op[0]=='=')) cmset(m, p->s, NULL);
		if(p->k==WP_ARI && p->arg) {
			char *t = fwstr(p->arg, m);
			if(t) {
				hkarith(t, m);
				free(t);
			} else if(p->arg->raw) hkarith(p->arg->raw, m);
		}
		if(p->arg) hkwd(p->arg, h, m);
		if(p->arg2) hkwd(p->arg2, h, m);
		for(int k = 0; k<p->ndq; k++) hkwd(p->dq[k], h, m);
	}
}

static void hkassigned(An *a, Cm *acc) {
	if(!a) return;
	if(a->k==N_SIMPLE) for(int i = 0; i+1<a->nas; i += 2) cmset(acc, a->as[i]->raw, "");
	if(a->k==N_FOR && a->name) cmset(acc, a->name, "");
	for(int i = 0; i<a->n; i++) hkassigned(a->v[i], acc);
	for(int i = 0; i<a->nci; i++) hkassigned(a->ci[i].body, acc);
}

static void hkforget(Cm *m, Cm *acc) {
	for(int i = 0; i<acc->c; i++) cmset(m, acc->n[i], NULL);
}

static int g_hkfun;

static int hkgrepf(const StrV *av) {
	for(int i = 1; i<av->n; i++) {
		const char *a = av->v[i];
		if(a[0]!='-' || !a[1] || strcmp(a, "--")==0) return 0;
		for(const char *q = a+1; *q; q++) {
			if(*q=='f') return q[1] || i+1<av->n;
			if(*q=='e') {
				if(!q[1]) i++;
				break;
			}
		}
	}
	return 0;
}

static void hksimple(An *a, Hks *h, Cm *m) {
	for(int i = 0; i<a->nw; i++) hkwd(a->w[i], h, m);
	for(int i = 1; i<a->nas; i += 2) hkwd(a->as[i], h, m);
	for(int i = 0; i<a->nrd; i++) hkwd(a->rd[i].w, h, m);
	if(!a->nw) {
		for(int i = 0; i+1<a->nas; i += 2) {
			char *v = fwstr(a->as[i+1], m);
			cmset(m, a->as[i]->raw, v);
			free(v);
		}
		return;
	}
	StrV av = {0};
	int ok = 1;
	for(int i = 0; ok && i<a->nas; i += 2) {
		char *v = hkstr0(a->as[i+1]);
		if(!v) ok = 0;
		free(v);
	}
	for(int i = 0; ok && i<a->nw; i++) if(!fwfields(a->w[i], m, &av)) ok = 0;
	const char *cmd = av.n ? av.v[0] : NULL;
	if(ok && cmd) {
		int al = 0;
		for(int i = 0; g_hkok[i]; i++) if(strcmp(g_hkok[i], cmd)==0) al = 1;
		if(al && strcmp(cmd, "grep")==0 && hkgrepf(&av)) al = 0;
		if(al && !a->hk) {
			if(h->n==h->cap) {
				h->cap = h->cap ? h->cap*2 : 16;
				h->v = realloc(h->v, sizeof(Hkg)*(size_t)h->cap);
			}
			h->v[h->n++] = (Hkg){0};
			a->hk = h->n;
		}
		if(al) {
			Hkg *gp = &h->v[a->hk-1];
			int dup = 0;
			for(int i = 0; i<gp->n && !dup; i++) {
				if(gp->v[i].av.n!=av.n) continue;
				int k = 0;
				while(k<av.n && strcmp(gp->v[i].av.v[k], av.v[k])==0) k++;
				dup = k==av.n;
			}
			if(!dup && gp->n<256) {
				if(gp->n==gp->cap) {
					gp->cap = gp->cap ? gp->cap*2 : 4;
					gp->v = realloc(gp->v, sizeof(Hk)*(size_t)gp->cap);
				}
				Hk *k = &gp->v[gp->n++];
				k->fn = gen_hook(h->g, &av, a, m);
				k->av = av;
				av = (StrV){0};
			}
		}
	}
	for(int i = 0; i<av.n; i++) free(av.v[i]);
	free(av.v);
	if(!a->nw) return;
	char *n0 = hkstr0(a->w[0]);
	if(!n0) return;
	if(strcmp(n0, "eval")==0 || strcmp(n0, ".")==0 || strcmp(n0, "source")==0) cmclear(m);
	else if(strcmp(n0, "read")==0 || strcmp(n0, "unset")==0 || strcmp(n0, "getopts")==0) {
		for(int i = 1; i<a->nw; i++) {
			char *x = hkstr0(a->w[i]);
			if(x) {
				if(isalpha((unsigned char)*x) || *x=='_') cmset(m, x, NULL);
				free(x);
			}
		}
		if(strcmp(n0, "read")==0) cmset(m, "REPLY", NULL);
		cmset(m, "OPTARG", NULL);
		cmset(m, "OPTIND", NULL);
	} else if(strcmp(n0, "export")==0 || strcmp(n0, "readonly")==0 || strcmp(n0, "local")==0 || strcmp(n0, "declare")==0 || strcmp(n0, "typeset")==0) {
		for(int i = 1; i<a->nw; i++) {
			char *x = hkstr0(a->w[i]);
			char *eq = x ? strchr(x, '=') : NULL;
			if(eq) {
				*eq = 0;
				cmset(m, x, eq+1);
			} else if(x && strcmp(n0, "local")==0) cmset(m, x, NULL);
			free(x);
		}
	} else if(strcmp(n0, "let")==0) cmclear(m);
	else if(g_hkfun) {
		for(struct fnl *f = g_fnl; f; f = f->next) if(strcmp(f->name, n0)==0) hkforget(m, &f->as);
	}
	free(n0);
}

static void hkwalk(An *a, Hks *h, Cm *m) {
	if(!a) return;
	switch(a->k) {
	case N_SIMPLE:
		hksimple(a, h, m);
		return;
	case N_SUB:
	case N_PIPE: {
		for(int i = 0; i<a->nrd; i++) hkwd(a->rd[i].w, h, m);
		for(int i = 0; i<a->n; i++) {
			Cm s = cmdup(m);
			hkwalk(a->v[i], h, &s);
			cmfree(&s);
		}
		return;
	}
	case N_FUNC: {
		struct fnl *f = calloc(1, sizeof(*f));
		f->name = strdup(a->name);
		hkassigned(a->v[0], &f->as);
		f->next = g_fnl;
		g_fnl = f;
		g_hkfun = 1;
		Cm s = cmdup(m);
		hkwalk(a->v[0], h, &s);
		cmfree(&s);
		return;
	}
	case N_FOR: {
		for(int i = 0; i<a->nw; i++) hkwd(a->w[i], h, m);
		StrV it = {0};
		int lit = !a->noin;
		for(int i = 0; lit && i<a->nw; i++) if(!fwfields(a->w[i], m, &it)) lit = 0;
		if(lit && it.n>0 && it.n<=512 && h->budget>=it.n) {
			h->budget -= it.n;
			Cm acc = {0};
			hkassigned(a, &acc);
			for(int i = 0; i<it.n; i++) {
				cmset(m, a->name, it.v[i]);
				hkwalk(a->v[0], h, m);
			}
			hkforget(m, &acc);
			cmfree(&acc);
			cmset(m, a->name, NULL);
			for(int i = 0; i<it.n; i++) free(it.v[i]);
			free(it.v);
			return;
		}
		for(int i = 0; i<it.n; i++) free(it.v[i]);
		free(it.v);
		cmset(m, a->name, NULL);
		break;
	}
	case N_ARFOR:
		for(int i = 0; i<3; i++) hkarith(a->ex[i], m);
		break;
	case N_ARITH:
		hkarith(a->ex[0], m);
		break;
	case N_CASE:
		hkwd(a->word, h, m);
		break;
	default:
		break;
	}
	for(int i = 0; i<a->nw && a->k!=N_FOR; i++) hkwd(a->w[i], h, m);
	for(int i = 0; i<a->nrd; i++) hkwd(a->rd[i].w, h, m);
	int branch = a->k==N_IF || a->k==N_WHILE || a->k==N_UNTIL || a->k==N_FOR || a->k==N_ARFOR || a->k==N_CASE || a->k==N_AND || a->k==N_OR;
	Cm acc = {0};
	if(branch) {
		hkassigned(a, &acc);
		if(a->k!=N_IF && a->k!=N_CASE && a->k!=N_AND && a->k!=N_OR) hkforget(m, &acc);
	}
	for(int i = 0; i<a->n; i++) {
		if(a->v[i]->bg) {
			Cm s = cmdup(m);
			hkwalk(a->v[i], h, &s);
			cmfree(&s);
		} else hkwalk(a->v[i], h, m);
	}
	for(int i = 0; i<a->nci; i++) {
		for(int j = 0; j<a->ci[i].np; j++) hkwd(a->ci[i].pat[j], h, m);
		hkwalk(a->ci[i].body, h, m);
	}
	if(branch) {
		hkforget(m, &acc);
		cmfree(&acc);
	}
}

static void bnwd(Wd *w, char *need, int *full);

static void bnwalk(An *a, char *need, int *full) {
	if(!a || *full) return;
	if(a->k==N_SIMPLE && a->nw) {
		char *n = hkstr0(a->w[0]);
		if(!n) *full = 1;
		else {
			static const char *const dyn[] = {"eval", ".", "source", "command", "type", "trap", NULL};
			for(int i = 0; dyn[i]; i++) if(strcmp(dyn[i], n)==0) *full = 1;
			for(int i = 0; i<RT_NB; i++) if(strcmp(g_rtb[i].n, n)==0) need[i] = 1;
			free(n);
		}
	}
	for(int i = 0; i<a->nw; i++) bnwd(a->w[i], need, full);
	for(int i = 0; i<a->nas; i++) bnwd(a->as[i], need, full);
	for(int i = 0; i<a->nrd; i++) bnwd(a->rd[i].w, need, full);
	if(a->word) bnwd(a->word, need, full);
	for(int i = 0; i<3; i++) if(a->exw[i]) bnwd(a->exw[i], need, full);
	for(int i = 0; i<a->n; i++) bnwalk(a->v[i], need, full);
	for(int i = 0; i<a->nci; i++) {
		for(int j = 0; j<a->ci[i].np; j++) bnwd(a->ci[i].pat[j], need, full);
		bnwalk(a->ci[i].body, need, full);
	}
}

static void bnwd(Wd *w, char *need, int *full) {
	if(!w) return;
	for(int i = 0; i<w->n; i++) {
		Wp *p = &w->p[i];
		if(p->cmd) bnwalk(p->cmd, need, full);
		if(p->arg) bnwd(p->arg, need, full);
		if(p->arg2) bnwd(p->arg2, need, full);
		for(int k = 0; k<p->ndq; k++) bnwd(p->dq[k], need, full);
	}
}

static void rel32at(Code *c, size_t at, size_t target);

static size_t rtlink(Gen *g, An *root, size_t *btpos, int *nbt) {
	Code *c = &g->code;
	char *bneed = calloc(RT_NB+1, 1);
	int full = 0;
	bnwalk(root, bneed, &full);
	if(full) memset(bneed, 1, RT_NB);
	char *sn = calloc(RT_NS, 1);
	sn[RT_ESEC] = 1;
	for(int i = 0; i<RT_NB; i++) if(bneed[i]) sn[g_rtb[i].sec] = 1;
	int *xi = calloc((size_t)g->nx+1, sizeof(int));
	for(int k = 0; k<g->nx; k++) {
		xi[k] = -1;
		for(int i = 0; i<RT_NX; i++) if(strcmp(g_rtx[i].n, g->xn[k])==0) xi[k] = i;
		if(xi[k]<0) {
			fprintf(stderr, "sh2elf: runtime symbol %s missing\n", g->xn[k]);
			exit(1);
		}
		sn[g_rtx[xi[k]].sec] = 1;
	}
	for(int ch = 1; ch;) {
		ch = 0;
		for(int i = 0; i<RT_NR; i++) if(sn[g_rtr[i].sec] && !sn[g_rtr[i].tsec]) {
			sn[g_rtr[i].tsec] = 1;
			ch = 1;
		}
	}
	size_t *pos = calloc(RT_NS, sizeof(size_t));
	for(int i = 0; i<RT_NS; i++) {
		if(!sn[i]) continue;
		while(cpos(c) % g_rts[i].align) c8(c,0xCC);
		pos[i] = cpos(c);
		bput(&c->code, g_rtd+g_rts[i].off, g_rts[i].size);
	}
	for(int i = 0; i<RT_NR; i++) {
		if(!sn[g_rtr[i].sec]) continue;
		size_t P = pos[g_rtr[i].sec]+g_rtr[i].at;
		size_t T = (size_t)((int64_t)pos[g_rtr[i].tsec]+g_rtr[i].tadd);
		if(g_rtr[i].typ==2) {
			int32_t d = (int32_t)((int64_t)T-(int64_t)P);
			memcpy(c->code.data+P, &d, 4);
		}
		else {
			memset(c->code.data+P, 0, 8);
			crel(g, P, T);
		}
	}
	for(int k = 0; k<g->nx; k++) rel32at(c, g->xa[k], pos[g_rtx[xi[k]].sec]+g_rtx[xi[k]].off);
	free(xi);
	int nb = 0;
	size_t *np = calloc(RT_NB+1, sizeof(size_t));
	for(int i = 0; i<RT_NB; i++) {
		if(!bneed[i]) continue;
		np[i] = cpos(c);
		bput(&c->code, g_rtb[i].n, strlen(g_rtb[i].n)+1);
		nb++;
	}
	while(cpos(c) & 7) c8(c,0);
	*btpos = cpos(c);
	for(int i = 0; i<RT_NB; i++) {
		if(!bneed[i]) continue;
		size_t at = cpos(c);
		uint64_t e3[3] = {0, 0, (uint64_t)(int64_t)g_rtb[i].special};
		bput(&c->code, e3, sizeof(e3));
		crel(g, at, np[i]);
		crel(g, at+8, pos[g_rtb[i].sec]+g_rtb[i].off);
	}
	if(!nb) {
		uint64_t z3[3] = {0};
		bput(&c->code, z3, sizeof(z3));
	}
	*nbt = nb;
	size_t ent = pos[RT_ESEC]+RT_EOFF;
	free(np);
	free(pos);
	free(sn);
	free(bneed);
	return ent;
}

static void rel32at(Code *c, size_t at, size_t target) {
	int32_t d = (int32_t)((int64_t)target-(int64_t)(at+4));
	memcpy(c->code.data+at, &d, 4);
}

static void gen_rt(Gen *g, An *root) {
	g->rtok = 1;
	binit(&g->code.code);
	sp_init(&g->strs);
	g->rels = (Rels){0};
	g->bss_off = 0;
	g->status_off = g->bss_off;
	g->bss_off += 8;
	g->sp_off = g->bss_off;
	g->bss_off += 8;
	g->bg_off = g->bss_off;
	g->bss_off += 8;
	g->scr_off = g->bss_off;
	g->bss_off += 256;
	Code *c = &g->code;
	mov_rdi_imm64(c, g->bss_base + g->sp_off);
	c8(c,0x48); c8(c,0x89); c8(c,0x27);
	c8(c,0x48); c8(c,0x89); c8(c,0xE7);
	c8(c,0x48); c8(c,0x83); c8(c,0xE4); c8(c,0xF0);
	c8(c,0x48); c8(c,0x8D); c8(c,0x35);
	size_t pa = cpos(c);
	c32(c,0);
	c8(c,0x48); c8(c,0x8D); c8(c,0x15);
	size_t ph = cpos(c);
	c32(c,0);
	c8(c,0xB9);
	size_t pn = cpos(c);
	c32(c,0);
	c8(c,0x4C); c8(c,0x8D); c8(c,0x05);
	size_t pb = cpos(c);
	c32(c,0);
	c8(c,0x41); c8(c,0xB9);
	size_t pnb = cpos(c);
	c32(c,0);
	c8(c,0xE8);
	size_t pe = cpos(c);
	c32(c,0);
	c8(c,0xF4);
	Hks h = {0};
	h.g = g;
	h.budget = 20000;
	Cm m = {0};
	hkwalk(root, &h, &m);
	cmfree(&m);
	uint32_t nh = (uint32_t)h.n;
	memcpy(c->code.data+pn, &nh, 4);
	while(cpos(c) & 15) c8(c,0xCC);
	Sz z = {0};
	binit(&z.b);
	size_t ro = szan(&z, root);
	size_t ab = cpos(c);
	bput(&c->code, z.b.data, z.b.len);
	for(size_t i = 0; i<z.nr; i++) {
		uint64_t t;
		memcpy(&t, z.b.data+z.rl[i], 8);
		crel(g, ab+z.rl[i], ab+t);
	}
	free(z.b.data);
	free(z.rl);
	rel32at(c, pa, ab+ro);
	while(cpos(c) & 7) c8(c,0);
	size_t *gpos = calloc((size_t)h.n+1, sizeof(size_t));
	for(int gi = 0; gi<h.n; gi++) {
		Hkg *gp = &h.v[gi];
		size_t *avp = calloc((size_t)gp->n+1, sizeof(size_t));
		for(int i = 0; i<gp->n; i++) {
			size_t *sp = calloc((size_t)gp->v[i].av.n+1, sizeof(size_t));
			for(int k = 0; k<gp->v[i].av.n; k++) {
				sp[k] = cpos(c);
				bput(&c->code, gp->v[i].av.v[k], strlen(gp->v[i].av.v[k])+1);
			}
			while(cpos(c) & 7) c8(c,0);
			avp[i] = cpos(c);
			for(int k = 0; k<gp->v[i].av.n; k++) {
				size_t at = cpos(c);
				uint64_t zz = 0;
				bput(&c->code, &zz, 8);
				crel(g, at, sp[k]);
			}
			uint64_t zz = 0;
			bput(&c->code, &zz, 8);
			free(sp);
		}
		gpos[gi] = cpos(c);
		for(int i = 0; i<gp->n; i++) {
			size_t at = cpos(c);
			uint64_t w3[3] = {0, (uint64_t)gp->v[i].av.n, 0};
			bput(&c->code, w3, sizeof(w3));
			crel(g, at, gp->v[i].fn);
			crel(g, at+16, avp[i]);
		}
		free(avp);
	}
	size_t ht = cpos(c);
	for(int gi = 0; gi<h.n; gi++) {
		size_t at = cpos(c);
		uint64_t w2[2] = {(uint64_t)h.v[gi].n, 0};
		bput(&c->code, w2, sizeof(w2));
		crel(g, at+8, gpos[gi]);
	}
	if(!h.n) {
		uint64_t zz[2] = {0};
		bput(&c->code, zz, sizeof(zz));
	}
	free(gpos);
	rel32at(c, ph, ht);
	while(cpos(c) & 15) c8(c,0xCC);
	size_t btp = 0;
	int nbt = 0;
	size_t ent = rtlink(g, root, &btp, &nbt);
	rel32at(c, pb, btp);
	uint32_t nb32 = (uint32_t)nbt;
	memcpy(c->code.data+pnb, &nb32, 4);
	rel32at(c, pe, ent);
	for(int gi = 0; gi<h.n; gi++) {
		for(int i = 0; i<h.v[gi].n; i++) {
			for(int k = 0; k<h.v[gi].v[i].av.n; k++) free(h.v[gi].v[i].av.v[k]);
			free(h.v[gi].v[i].av.v);
		}
		free(h.v[gi].v);
	}
	free(h.v);
}

static void gen_script(Gen *g, Script *sc) {
	binit(&g->code.code);
	sp_init(&g->strs);
	g->rels=(Rels) {
		0
	};
	g->bss_off=0;
	g->status_off=g->bss_off;
	g->bss_off+=8;
	g->sp_off=g->bss_off;
	g->bss_off+=8;
	g->bg_off=g->bss_off;
	g->bss_off+=8;
	g->scr_off=g->bss_off;
	g->bss_off+=256;
	g->tb_off=0;
	g->out_off=0;
	g->wt_pos=0;
	g->ct_pos=0;
	g->ct_pg=0;
	g->ct_pl=0;
	g->ct_rs=0;
	g->ct_by=0;
	g->ct_p0=0;
	mov_rdi_imm64(&g->code, g->bss_base + g->sp_off);
	c8(&g->code,0x48); c8(&g->code,0x89); c8(&g->code,0x27);
	for(int i=0; i<sc->n; i++) {
		ScriptEntry *ent=&sc->v[i];
		Pipeline *pl=&ent->pl;
		size_t skip=0;
		if(ent->cond!=COND_ALWAYS) {
			load_status_eax(&g->code,g);
			c8(&g->code,0x85);
			c8(&g->code,0xC0);
			if(ent->cond==COND_PREV_SUCCESS) skip=jne_rel32(&g->code);
			else skip=je_rel32(&g->code);
		}
		if(pl->bg) {
			sys_fork(&g->code);
			c8(&g->code,0x48); c8(&g->code,0x85); c8(&g->code,0xC0);
			size_t jp = jne_rel32(&g->code);
			emit_pl(g,pl);
			load_status_eax(&g->code,g);
			mov_rdi_rax(&g->code);
			sys_exit(&g->code);
			patch_here(&g->code, jp);
			mov_rdi_imm64(&g->code, g->bss_base + g->bg_off);
			c8(&g->code,0x48); c8(&g->code,0x89); c8(&g->code,0x07);
			store_status_imm(&g->code,g,0);
		} else {
			emit_pl(g,pl);
			if(pl->neg) {
				load_status_eax(&g->code,g);
				c8(&g->code,0x85); c8(&g->code,0xC0);
				setst(&g->code,0x94);
				store_status_rax(&g->code,g);
			}
		}
		if(skip) patch_here(&g->code, skip);
	}
	load_status_eax(&g->code, g);
	c8(&g->code, 0x48); c8(&g->code, 0x89); c8(&g->code, 0xC7);
	sys_exit(&g->code);
}

static void dump_ir(Script *sc) {
	printf("=== IR DUMP ===\n");
	for(int i=0; i<sc->n; i++) {
		ScriptEntry *ent = &sc->v[i];
		printf("IR_STATEMENT cond=%d stages=%d\n", ent->cond, ent->pl.n);
		for(int j=0; j<ent->pl.n; j++) {
			Stage *st = &ent->pl.v[j];
			printf("  IR_STAGE argc=%d cmd=%s\n", st->argv.n, st->argv.n?st->argv.v[0]:"");
			for(int k=0; k<st->argv.n; k++) {
				printf("    IR_ARG idx=%d val=%s\n", k, st->argv.v[k]);
			}
		}
	}
}

static void list_code(Gen *g) {
	printf("=== DISASSEMBLY LISTING ===\n");
	for(size_t i=0; i<g->code.code.len; i++) {
		printf("%08zx: %02x\n", i, g->code.code.data[i]);
	}
}

static void fusage(const char *arg0) {
	fprintf(stderr,"usage: %s script.sh [-o a.out] [--dump-ir] [--list] [--emit-obj]\n", arg0);
}

int main(int argc, char **argv) {
	if(argc<2) {
		fusage(argv[0]);
		return 1;
	}
	const char *in=NULL, *out="a.out";
	int flag_dump_ir=0, flag_list=0, flag_emit_obj=0, flag_old=0, flag_ast=0;
	for(int i=1; i<argc; i++) {
		if(strcmp(argv[i],"-o")==0 && i+1<argc) out=argv[++i];
		else if(strcmp(argv[i],"--old-core")==0) flag_old=1;
		else if(strcmp(argv[i],"--dump-ast")==0) flag_ast=1;
		else if(strcmp(argv[i],"--dump-ir")==0) flag_dump_ir=1;
		else if(strcmp(argv[i],"--list")==0) flag_list=1;
		else if(strcmp(argv[i],"--emit-obj")==0) flag_emit_obj=1;
		else if(argv[i][0]!='-') in=argv[i];
		else {
			fprintf(stderr,"unknown arg: %s\n", argv[i]);
			return 1;
		}
	}
	if(!in) {
		fusage(argv[0]);
		return 1;
	}
	char *src=readfile(in);
	Gen g= {0};
	g.bss_base=0x10000000;
	if(!flag_old && !flag_dump_ir) {
		char err[256];
		An *ast = sparse(src, err, sizeof(err));
		if(!ast) {
			fprintf(stderr, "%s: %s\n", in, err);
			return 2;
		}
		if(flag_ast) {
			adump(stdout, ast, 0);
			return 0;
		}
		gen_rt(&g, ast);
	} else {
		Script sc=parse(src);
		if(flag_dump_ir) {
			dump_ir(&sc);
			return 0;
		}
		gen_script(&g,&sc);
	}
	if(flag_list) {
		list_code(&g);
		return 0;
	}
	write_elf(out,&g);
	if(flag_emit_obj) {
		fprintf(stderr,"wrote relocatable object to %s\n", out);
	} else {
		fprintf(stderr,"wrote ELF64 x86_64 to %s\n", out);
	}
	return 0;
}
